-- theater.plays: 192 rows
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('1', 'The John Wayne Principle', 'by Tony McNamara', 'A searing portrait of the insidious attractions of corporate life, "The John Wayne Principle" tells the story a cynical, anti-establishment trust-fund kid who is picked to succeed his father as CEO of a multinational corporation.  Instead of turning down the post, as his ambitious, business-minded sister had expected, he decides to sign on for a year, sending the company''s stock into a tailspin.  His sister''s attempts to undermine his tenure only serve to fuel his enthusiasm for the job, and, as their sibling rivalry takes on sexual-political overtones, one is left to wonder if this rebel riding rough-shod on the company wants to break or break in the system.', 'Festival');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('2', 'Men', 'by Brendon Cowell', 'Guy, Jules & Crazy Bob find themselves trapped in the most important hour of their lives as they struggle to define who they are, what they have done, and the type of MEN they will become when it is all over. Strangely lorded over by the disembodied female voice of Haizel, and the terrifying approach of the ‘end'', so begins a wildly energetic and often dangerous romp through the dark side of masculinity and beyond...', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('3', 'The Secret Narrative Of The Phone Book', 'By Gordon Cox, directed by Suzanne Agins', 'A romantic comedy hijacked by a conspiracy thriller.  It follows a sexy freedom fighter''s daring plan to corrupt a global media conglomerate by seducing two of its employees at the same time. Its tongue-in-cheek techno-paranoia seriously questions the possibility of a genuine connection between human beings', 'Festival');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('4', 'Ludlow Fair', 'by Lanford Wilson', 'A winsome one-act by Lanford Wilson that offers a glimpse into the lives of two twentysomething roommates, broke and lonely and crammed into their tiny first apartment in Manhattan.  A production of recent Northwestern alums.', 'Kids');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('5', 'BYE MOM! Or, How NOT to Bury Your Mother', 'By Susan Austin Roth', 'Take one Jewish mother too stubborn to die, an obsessed daughter and her married lover, three sons: a nebbish, a nerd, and an airhead.  Toss in an insufferable daughter-in-law and convene them all in Florida.  And what do you get?  A nasty little comedy about the lack of family values and the joy of family feuding', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('6', 'Tricks of the Trade', 'Written and directed by John Capo', 'A world premiere drama about four young gay men during one very, very long night at a West Village bar as they look for Mr. Right, Mr. Right Now, and whomever else they can find to pass the time and ease their needs. A play William M. Hoffman, author of "As Is," calls "''The Boys in the Band'' for this generation."
', 'Classical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('7', 'Waiting For Godot', 'Samuel Beckett', 'Waiting for Godot...an all time classic...a comic tragic play that speaks of human perplexity, of kindness, of hope.  The characters are reduced to mere waiting, in game playing to endure the waiting and the audience wonders whether Godot will ever come. Beckett''s symbolic character brings an unease that makes room for imagining and interpretation in reference to anything outside of itself...the absurdity of life itself!

', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('8', 'The Pinter Project', 'directed by Terry Schreiber', 'Two Pinter Plays- The Birthday Party and The Homecoming - in Rotating Repertory

The Homecoming offers a darkly comedic view of feminine power, while The Birthday Party explores the destruction of the artist by powerful authoritarian figures.

Schedule varies – call ahead or go to www.pinterproject.com for info.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('10', '12 Angry Women', 'written and directed by Elias Stimac', 'If hell hath no fury  like a woman scorned – well, imagine a dozen of them at one time!  A comedy for women and the men who infuriate them,  Featuring  sketches, spoofs and solos, this sexy, sassy showcase examines the reasons why  many females get burned, get mad, then get even.
', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('12', 'Yet To Evolve', 'Brandi Webb', 'This play shows how we must all evolve in order to live a happier life. For some, evolve can mean to get over the past and forgive, for others evolve can mean learning to accept those that are different from us.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('13', 'His Hers And Ours', 'by Clique Brown', 'Reaching the American dream sometimes means walking a path of obstacles. 
But, in breaking barriers, one can learn, grow and change.

An amusing battle of the sexes that takes place somewhere in the south sometime in the 1940s. "His, Hers and Ours" is the story of budding entrepreneurs and best friends Rita Jones and Thelma Lou, who partner to open a beauty shop -  right next door to Burt Carlson''s barbershop. Burt, a man who thinks that woman should stay at home, cook, clean and take care of children, is not pleased by the new business in town. Loudly complaining to his customers and cohorts about the space being rented to "a bunch of hens," not to mention the potential loss of their Friday night crap games, he threatens them with banishment from his establishment if any go to her aid.

Rita and Burt snap and snarl at each other, but with the help of Bullah Dillard, the preachers wife, and Billy Thornton, a talented young handyman who longs for a high school diploma, the two beauticians get their business up and running. Burt and Rita eventually manage to reach a flirtatious meeting of the minds and he with his and she with hers go on to reach an understanding that leads to what becomes Ours.

', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('14', 'The Owl & The Pussycat', 'By Bill Manhoff, Directed by Zina Jasper', 'A revival of the 1964 hit Broadway comedy about a sexually repressed writer and a prostitute


', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('15', 'The Swan', 'by Elizabeth Egloff', 'Fierce in its treatment of love, THE SWAN provides a mysterious gloss on whether or not we descended from the beasts and what we may feel when we find them lurking in our truest selves.  <p><p>"A bewitching bedtime story for grown-ups...a psycho-sexual cauldron wherein fantasy and deprivation merge and combust. Egloff''s language alternates be-tween the unadorned cadences of the workaday world and the lyric fancies of poets, her stage pictures shift from an implacable reality to florid dream states." —NY Newsday.<p><p>NOTE: Were we to use a movie rating system we would label this PG-13 as there are both violent and sensual moments and the shooting of a gun onstage.<p><p><p>', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('16', 'Shakin'' The Mess Outta Misery', 'by Shay Youngblood', 'SHAKIN'' THE MESS OUTTA MISERY combines storytelling, music and dance to recount a young black girl''s coming of age in the South in the 1960''s. Daughter, the 25-year-old narrator whose mother died when she was young, was raised by the women in the community.  At the age of 12, she begins her journey to womanhood guided by these very diverse, non-traditional, older black women.  As she reflects, Daughter becomes a child again reliving her vivid memories of growing up and recalling the lessons she learned.

', 'Classical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('17', 'The Colored Museum', 'George C. Wolfe', 'Look Two Hands, LLC, a Brooklyn-based theater company showcasing the talent of African American writers and actors invites you to join them in exploring the African American struggle to both honor and escape the legacy of suffering that is their past.  The Colored Museum mixes satire, sadness, jubilation attitude and joy to create an evening of theater that will entertain and provoke.', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('18', 'The Furies', 'By Trudy Hellier and Elise McCredie', 'A dark comedy, THE FURIES provides a merciless view of an established Melbourne suburb, where a sudden matricide creates suspicion and paranoia among its well-heeled inhabitants.  The unknown killer in their midst has everyone looking at one another in a new light.  When a fifty-something mother fails to appear at an important family function, obsessive fear finds a voice.  As suspicion grows, high emotions, paranoia, insecurity and greed emerge. 
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('19', 'Blackout', 'Some things are clearer in the dark...', 'At 4:10 PM on August 14, 2003, a power failure caused the electricity to stop flowing to the Northeastern United States and parts of Canada. The power was out for over 19 hours.

In a Manhattan studio apartment, Sean Ryan was taking the day off from work, shirking his responsibilities and reevaluating his life. He hated his job, his friends, and anyone who in any way reminded him of himself.

When the lights went out, his girlfriend came over to wait it out with him. They discussed their likes, their dislikes, and where they''d always thought they''d be at this point in their lives.

And that''s when his other girlfriend showed up.

It was going to be a long night.
', 'Costume Design');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('20', 'Yankee Doodle Boy', 'written and directed by Chip Deffaa', 'The latest in Chip Deffaa''s series of shows celebrating the music of George M. Cohan

You''ll hear not just such rousing Cohan classics as "You''re a Grand Old Flag," "Give My Regards to Broadway," and "45 Minutes from Broadway," but a delightful assortment of  rediscoveries--rich with sentiment, syncopation, wit, and joyously life-affirming melody.  The music--from ragtime to marches to vaudeville specialties--is pure Americana.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('21', 'The Gregor & Olga Show', '1947 Production Presents', 'A show about Love, Lust and Loathing...

Hideous comedy ensues when a misantropic Weimar peot and his temptress Russian wife bring their disastrous European vaudeville show to 1947 New York City. A beautiful Burlesque dancer and a suave nightclub crooner become pawns in their constant one-upmanship. 

', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('22', 'The Imaginary Invalid', 'by Moliere, directed by Matthew Maguire', 'Moilere''s classic comedy from 1673 about a vitally healthy man who seeks refuge in hypochondira because he is wracked by unrequited love.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('23', 'Jabu', 'written and directed by Elizabeth Swados', 'A musical extravaganzia celebrating the life of Alfred Jarry, creator of the infamous Ubu Roi which took Paris by storm at the turn of the 20th Century.', 'Lighting');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('24', 'I Found Her Tied To My Bed', 'Written and directed by Jeff Tabnick', 'At Evergreen Manor Nursing Home, the hours are long, the staff is underpaid and the occupants are easy to kill.  When a reckless coworker intrudes upon Beth''s solitary life, Beth becomes infatuated and goes to extremes to understand her. But understanding does not necessarily produce a healthy relationship—sometimes it only produces corpses in this dark comedy.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('25', 'Good Christian...', 'by Frederick Vaughn', 'GOOD CHRISTIAN tells the "coming out" story of a shy high school teenager.


', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('26', 'Down The Road', 'By Lee Blessing, Directed by Devin Scott', 'Down the Road is a story of a husband and wife team who are writing a book about a serial killer.  As they are drawn further into his world they question whether their book will help society by uncovering why he murdered 19 women, or if they are simply making a celebrity out of him and inspiring others to do the same<p>', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('27', 'A Beginner’s Guide To Deicide', 'by Qui Ngyuen and Robert Ross Parker', 'A Beginner''s Guide To Deicide traces the epic odyssey of Lucy, a Catholic schoolgirl (and all-around whiz with a battle-axe), who''s seeking God--whom she considers unjust and evil--so that she can take The Big Guy out once and for all. Accompanied by her scientifically-minded sidekick Mary, the duo is helped along by evolutionist Charles Darwin, who tells them to go back to the dawn of time to find God. And so they do, engaging in hilariously gory battles along the way with the likes of The Pope, Frederich Neitzche, Dante Alighieri, Joan of Arc and Jesus Christ. It all leads to a final, all-or-nothing showdown with the Omnipotent One himself.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('28', 'Unveilings', 'By:   P.J. Gibson', 'Directed By: Chuck Patterson
Produced By: Hazel Dolphy
Co-Produced By: Robb Cheeks


UNVEILINGS   is the story of a strong African-American family, the WATERFORD''S, a people of deep lineage who are financially, intellectually and culturally sound.  A former college professor chooses to spend her last days on her parents estate.  On this, her birthday, she receives as gifts - revelations of lies, deception and cheated years with the man she loved. Three generations of women drive the plot of this play.  The themes of deception, jealousy, love, favorites and secrets manifests themselves in the tearing and torn relationships between mothers, daughters and sisters.  This beautiful work, is strong on character, set in  an appealing environment, exposing the ugliness people can do to one another, even if they share blood.
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('29', 'The Last Word', 'by Gamal Chasten', 'Mixing the lively pace of a three-ring circus with the soulful spirit of a New Orleans jazz processional, Gamal Abdel Chasten explores the hopes, dreams and regrets that accompany the death of a loved one in his music-theater piece The Last Word.', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('30', 'Pullman Wa', 'written and directed by Young Jean Lee', 'Young Jean Lee''s work is theater stripped bare. Pullman, WA continues Lee''s exploration of visceral, immediate theater, placing an emphasis on powerful language and raw emotion. It is funny, sometimes weird and often uncanny. Her work gets to the heart of the theatrical experience and uproots our expectations of what a play can be.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('31', 'Where Sleeping Gods Lie...', 'written and directed by Sharon Fogarty!', 'A new musical comedy written and directed by Sharon Fogarty!

Three nuns in the third world struggle in an abandoned missionary and find fame, fortune and love.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('32', 'Just Another Subway Ride', 'Original scenes by a number of writers', 'This showcase has 14 actors and is only an hour long.<p>The scenes are short and all around 3 min. each.<p>Great actors and funny scenes with a follow up of food and beverages, what more could you want?', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('33', 'SubUrbia', 'Eric Bogosian', 'The parking lot of a mini-mall convenience store is the private domain of three men in their very early twenties: Jeff, Buff and Tim. Jeff is a sometime student, Buff an easy-going party animal and Tim a virtual alcoholic Air Force vet. They talk trash, harass Nazeer, the Pakistani owner of the store and revel in their high-school glory days. They drink beer, get high, eat Oreos. Jeff ponders his problematic relationship with his artist girlfriend, Sooze, and Buff fantasizes a relationship with Sooze''s best friend, Bee-Bee, a nurses'' aide on the critical ward of the local hospital. The focal point of this evening is the arrival of an old high-school chum, Pony, and his female associate, Erica. Since Pony left Burnfield (the name of this fictional suburban town), he has gone on to become semi-famous fronting for a band that has an album on the charts and a video on MTV. In the course of the evening, all of the friends congregate in the parking lot. Once Pony arrives in his black limo, fascination with his success metamorphosizes into jealousy, then flowers into bitter anger. New liaisons evolve as Buff succeeds in wooing Bee-Bee; Tim discovers his splenetic misanthropy is a turn-on for Erica; and Pony turns Sooze''s restlessness to his advantage. The building tension between the friends is accentuated with absurd physical moments and sheer violence: Sooze performs her piece for the group; Tim beats up Nazeer; and Buff gives new definition to the term "wrecked." As the next day dawns, some of the group have found their way out of Burnfield while the rest are left to deal with a tragedy that could have been any of them.', 'Author');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('34', 'The Astronomer''s Triange', 'by Jordan Seavey', 'An astronomer, a waitress, and a cartographer find themselves in a disorienting, explosive, and unknown scientific state: love.

Every second, somewhere in the universe,  a star explodes and no one knows how or why.  Every second someone falls in or feels love, and no one knows why. What is this state we call "love"? Through The Astronomers Triangle, the members of CollaborationTown explore love: it''s secrets, science, lust, betrayal-and the fruit it bears.  Encompassing original music, movement and sharp humor this truly collaborative ensemble will guide you through the stars, comets and the origin of life, avoiding the blackholes that eagerly await to swallow us...all in the frame of a triangle.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('35', 'Big Top Machine', 'Created and performed by Kevin Augustine', 'An hour long puppet theatre piece about the circus,
sideshow and many other things that were but are no
more.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('37', 'Paradise', 'written and directed by Glyn O''Malley', 'A drama about two teenage girls (a Palestinian and an Israeli) trapped at the height of the Intifada that gripped the Middle East', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('38', 'Nightswimming', 'by Jeff Keilholtz', 'On August 28th, 1998, two sisters were killed in an automobile accident, and the world of two New York City police officers was turned upside down. We meet the two officers on the one year anniversary of the death of their wives, and are quickly introduced into the dichotomy of grief. Chris Tucker, a brilliant and promising plain-clothes investigator, walking as if asleep, suffering from chronic insomnia, has buried himself in an already obsessive workaholic existence. Danny Harper, abandoning the world of law enforcement, leaves behind all that he knew, corrupting himself within the depths of compulsive lying and the seclusion of personal chaos. 
Through their only contact, a phone conversation, once a month, every month, on the anniversary of the death of their wives, the weight of guilt, and the pressures of loss, spirals them both desperately through a quest for the taste of lost personal connection; and to its inexorable resolution, the effects of such a pursuit will leave not only a permanent mark on all involved, but prove in the end you can only save your own world.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('39', 'Servant Of Two Masters', 'directed by Holly Golden', 'Commedia del arté meets the Looney Tunes in Holly Golden''s Servant of Two Masters, a fast-paced, punky update of the Italian comedy classic. 

Wily servant Truffaldino attempts to slake the demands of his insatiable stomach by secretly taking on two jobs with two separate masters.  Twice the work means twice the food, right?  But what Truffaldino doesn''t know is that his masters - whom he must keep apart at all costs to succeed in his double-dealing plan - are actually looking for each other...  Confusion abounds in this comedy of sex, deception, food, and drag in sunny cartoon Italy. 
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('40', 'You Can Hook Up JUSt Cover Up', 'Alycia Parker', 'This play is about how HIV/AIDS IS spread around the African-American Community  through the Various socioeconmic background from upper middle class t o innercity poor.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('41', 'SHLAMMER: A Gangster Vaudeville', 'Written and choreographed by Dan Froot', 'A Dance Theatre piece', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('42', 'DRIVING WHILE BLACK and other Felonious Funk', 'written and directed by Ron Beverly', 'Model citizen Jonathan Q. Downing is pulled over by the cops for a ''minor'' traffic violation.  He is then arrested and molested and his beliefs will be tested - because Jonathan ends up on death row!  And that''s when the fun really begins.  Driving While Black & Other Felonious Funk also takes a sardonic look at the plethora of reality TV shows that currently clog the airwaves.  Jonathan is not only in prison, but he may also star in a new reality TV series, "Who Wants To Be On Death Row?" ', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('43', 'Haven', 'written and performed by Sarah Kahn', 'Playwright/performer Sara Kahn revisits her personal journey from musical comedy performer to human rights worker in a one-person play with music. HAVEN transports audiences from the war zones of Bosnia, Sierra Leone and Afghanistan to the back alleys of Newark to tell the stories of four extraordinary refugees the playwright encountered in her work.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('44', 'There are Crimes and Crimes (Intoxication)', 'by August Strindberg', 'Partly a comedy of manners and a melodrama of crime and detective work, the 1899 work is an exploration of conflicting desires and the pangs of conscience. The characters are young artistis, writers adn performers who populate the bohemian world of turn-of-the-century Paris.  In this provocative work, Strindberg projects human drives into a richly theatrical landscape of movement, sound, dance and images.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('45', 'Jagger Kaye''s On Going Acting Classes', 'Jagger Kaye', 'Learn from a working Actor ("ED", National Commercials, Dozens of films), 
Writer & Director (over 25 stage shows & 2 short films). 

Jagger is one of the most respected sources for outing acting/model scams and 
owns/operates the NYC areas most respected FREE casting groups - 
NYCCasting@yahoogroups.com - http://groups.yahoo.com/group/NYCCasting 

Jagger is also an Independent Casting Director & a Career Consultant (over 3 
dozen clients). 

Class: Acting For Beginners 

Taught by Jagger Kaye of NYCCASTING@yahoogroups & JKCasting 
A 4-week course beginning Sunday April 24th, 2005 

Schedule: Sundays 1:00 - 3:00pm (April 24th, May 1st, 15th, 22nd)
Class size only 8 students
Price: Only $110 for 4 classes 
Description: A course on how to begin as an actor. We will discuss the 
business of being an actor, Work on scripts. Prepare you to audition 
& most of all have FUN. 
Location: The Producers Club Theaters - 358 W.44th NYC 

&

COMEDIC ACTING class & a show!

Learn the difference between "sketch comedy" (someone falling down) & "comedic acting" (why that person fell down). The difference between SNL & a show like Frasier!

Taught by Jagger Kaye of NYCCASTING@yahoogroups & JKCasting
A 5-week course beginning Sunday April 24th, 2005

5 weeks of classes that end in a mini-show (45 - 60 minutes)
The dates are:
Sunday, April 24, 3-6pm
Sunday, May 1, 3-6pm
Sunday, May 15, 3-6pm
Sunday, May 22, 3-6pm
Sunday, June 5 3-7pm

Performance June 5 at 8pm

Cost for all is only $155 & that includes 2 comp tickets for the performance

Everyone will play 3+ characters in the presentation

This is for someone that would like to learn the nuances of comedy & can get a stage credit as well ... of course this will be a LOT of fun

Jagger Kaye
JaggerKayeClass@teacher.com', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('46', 'Seven 11.2005', 'directed by G.R. Johnson', 'Desipina & Company''s seven.11.2005 is a series of seven 11-minute plays set in the American convenience store, a dominant American consumer presence from coast to coast and the ideal symbol for the mini-productions which challenge and redefine existing stereotypes of immigrant convenience store employees while exploring the diversity of South Asian  nd Asian Pacific American cultural experiences. .

The seven plays for this year''s production are:
Paris by Anuvab Pal
An 11-minute conversation without consequence on a lazy Paris afternoon

S.A.M.O.S.A. by Debargo Sanyal
Students Ho, Cho and Mo get down and dirty with student club politics and deli snacks

Salesgirl by Celena Cipriaso
Two strangers at different points in their romantic relationship examine the nature of love

Beckoning Cat by J.P. Chan
Waiting for the lucky numbers at a convenience store can prove to be an unlucky business

Intimate with the Locals by Rachael Astarte Piccone
In malaria pill-induced paranoia, Evie, an insomniac writer, recounts her recent heartbreak in Bombay to Mohit, the store clerk who truly deserves her heart.

Color Me Desi by Rishi Chowdhary
A liquor-run to the convenience store before the big desi party uncovers there are more shades of brown than there are colors to Holi

SOONDERELLA: A fairy tale of a different colour
A new musical by Samrat Chakrabarti and Sanjiv Jhaveri 
After last year''s widely successful A Very Desi Christmas, a pop musical adaptation of Scrooge, SOONDERELLA is another 11-minute musical set in the convenience store

', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('47', 'COWS GONE WILD:  FCC Uncensored', 'bitches funny presents...', '"You won''t believe the hilarious sexy uncensored stuff our crew has caught them doing!  At the bar, on spring break, now in Manhattan... they''re milking it for all it''s worth...it''s crazy creamy candy for the eyes... it ''s udderly unbelievable...bitches funny presents COWS GONE WILD: FCC Uncensored!

Sketches cover such topics as the sexual objectification of farm animals, stalking, gender identity, the Bush presidency, mistreatment of the physically challenged, child care, the justice system, and NY Marathon.

Show features writer-performer (s) Mel Salvatore, Michelle Haun, Kerry Logston, and Elizabeth Van Meter.  

bitches funny originated in LA by creators Mel Salvatore and Missi Pyle in 1999.  The founding group of Ms. Salvatore, Ms. Pyle, Michelle Haun, Kari Gautier, and 
Christina Moore played to sold out audiences at The World Famous Comedy Store and The Second City Theatre.  In 2003, the group became Bi-coastal and added members Kerry Logston, Eileen O''Connell, and Elizabeth Van Meter.  In 2004, all the bitches proudly performed in the NY International Fringe Festival."
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('48', 'Fit To Kill', 'Victor L. Cahn', 'A suspense-thriller about strategy, deception, and betrayal. Adrian, a charming but self-indulgent chess master, lives a life of luxury thanks to his marriage to Janice, an older but sexy and vibrant woman, who has made her fortune as the CEO of an exercise empire. When Amy, a young reporter with an agenda of her own, starts asking too many questions, a whirlwind of deadly schemes ensue, leading to a series of twists and surprises that will keep audiences guessing until the final seconds.



', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('49', 'Dracula', 'Adapted and Directed by Matthew Hancock', 'Matthew Hancock''s adaptation of Bram Stoker''s Dracula tells the mythic story of Count Dracula and his victims through the eyes of his paramour, Mina, in a highly theatrical presentation. Combining stylized action sequences, video projections and dialogue peppered with a dose of contemporary pop-culture, this is the Dracula for the urban hipster of 2005. Running at a brisk, action packed 75 minutes this Dracula was inspired by the music of David Bowie and the comic book art of Mike Mignola (Hellboy).', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('50', 'Pith!', 'Written and directed by Steward Lemoine', 'Set in 1931, PITH! is an epic tale of travel and adventure told with the most economical means.  An itinerant sailor leads a grieving society widow and her stoic housekeeper on an exhilarating and treacherous journey into the heart of the South American jungle...without ever leaving the living room.  With only four dining room chairs and a phonograph, Jack Vail propels Virginia Tilford and Nancy Kimble from Providence, Rhode Island to New Orleans, Panama, and Ecuador, where hilarious encounters with a succession of explorers, shysters, gigolos, natives, and all manner of tropical wildfire have life-altering consequences for the ladies. 

', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('51', 'Not Yet Diagnosed (nervous) 1918', 'Directed by Randy Sharp', 'Not Yet Diagnosed (Nervous 1918) concerns the effects of the extreme shell shock suffered by WWW veterans following their service.  Set in an allied trench during 1918, a small group of American soldiers wake to find themselves abandoned by everyone on the battlefield, including the Germans.  On this desolate landscape everyone from the Army Photographic Corps specialist to the loneliest infantry solider tries to piece together what may have happened during the night?  Were they left behind? Is the war over?  Are they already home? Is there anybody out there?  A multimedia piece
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('52', 'The Rite Of The Serpent Skirt', 'by Dan Pulick, directed by Glynis Rigsby', 'The Rite of the Serpent Skirt – named after the ancient goddess of the Americas - takes place in present-day New York, where a frazzled nurse, Lily, tries desperately to survive her double life as both the caregiver to a young, handicapped girl, and as the wife of a wealthy business-man. Lily and four supporting female characters arrive at a critical moment in their lives when they must choose between the limiting comforts of the past or face the fear of moving on. And when their worlds unravel, the results are both devastating and enlightening.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('53', 'Rappacini''s Daughter', 'by Terry Quinn', '"Rappacini''s Daughter" takes place in Bergamo, Italy, where a botanist, Giacomo Rappacini, has armed his daughter, Beatrice, against the evils of the world by confining her in a garden and raising her among the perfumes of poisonous plants.  Manipulated by Pietro Baglioni, a jealous professional rival of Rappacini, a vain and worldly suitor named Giovanni gains access to Beatrice and falls in love with her in the splendid, deadly garden. In time, Giovanni becomes inured to the plants'' toxins but becomes as poisonous as Beatrice.  Unable to overcome his dismay at this, he lashes out at the young woman, and as the unwitting agent of Baglioni''s vendetta, kills her.

"Rappacini''s Daughter" is a world premiere.

This one act play is on a double bill. See Also: <a href="http://www.onoffoff.com/playbill.xzc?PK=11098">Bad Evidence</a>



', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('54', 'Hard Right', 'written and directed by David Barth', 'A slacker college student brings his girlfriend home for a visit with the folks but family tensions turn into family trauma when a "counselor" conducting a dubious field study pays them a visit.  The timeless conflict between liberty and absolute power is reexamined in this darkly comic parable set on the eve of the age of terror.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('55', 'Edward II', 'The First Great History Play in English', 'Edward II, the first great history play in English, tells the story of the problematic reign and tragic death of Edward II, who reigned from 1307-1327.  Edward was unable to control the rebellious English barons and was defeated miserably by the Scots in the Battle of Bannockburn.  His reign was further complicated by his infatuation with two homosexual lovers--first Piers Gaveston, then Hugh Spencer (an ancestor of the late Princess of Wales).  All of this makes for a a tremendously exciting play.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('56', 'The Two Gentlemen Of Verona', 'by William Shakespeare', 'Shakespeare''s rarely-done early comedy foreshadows many of the delightful characters, zany plots and lively humor that mark all his comedies.  And, it has a dog!  Presented in the usual Deptford style – uncut and set in the time and place the playwright set the action.












(Brennan Roberts (as Launce, with his dog, Crab)
in THE TWO GENTLEMEN OF VERONA.)', 'Producer');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('57', 'Bad Evidence', 'by Terry Quinn', '"Bad Evidence" is a contemporary play in which a young, attractive married couple is agonizing over suspicion of infidelity. The couple, talking in bed after hosting a party, become increasingly hostile in their language and actions. Sex for them becomes a slow, spider-like dance in which each tries to release inhibitions and tempt the other partner into humiliating confessions by the use of "bad evidence."

"Bad Evidence" is a NY premiere 

This one act play is on a double bill. See Also -<a href="http://www.onoffoff.com/playbill.xzc?PK=11080"> Rappacini''s Daughter</a>', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('58', 'The House of Blue Leaves', 'by John Guare, directed by Ted Sod', 'House of Blue Leaves takes place on Oct. 4, 1965 when the Pope is coming to New York to try to end the war in Vietnam.  Artie Shaughnessy, a native of Queens, wants to change his life.  He dreams of a life in Hollywood as a composer instead of being the Central Park Zookeeper he is.  At home, his mentally unstable wife, Bananas, has been living in her nightgown for 6 months.  His mistress, Bunny, wants to get married and escape to Bel Air.  To add to his troubles, his son, Ronnie, is AWOL from the Army; three nuns show up at his apartment in search of a T.V., and a movie starlet drops by for a visit.  ', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('59', 'Media Killed The Video Star', 'The 80''s cabaret-dramedy!', 'A young boy dreams of growing up to be a ''Solid Gold'' dancer, but the influences of the 80''s (bad hair, music videos, drugs, sex, rock and roll and cheesy dance moves) overloads the senses of a failed music video star''s visions.  Filled with a jukebox of 80''s pop, new wave and one hit wonders, this cabaret show is fun for any pop culture junkie with hundreds of references about hits and misses, personalities, trends and trendsetters and artists and Tv shows of the ''Me'' generation. 
Written/Performed by Alex Perez (DeLaGuarda, OZ, MTV) and some special guests.....this 90 minute show also features food/drinks and 80''s dance party before and after the show!', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('60', 'Keanu Reeves Saves the Universe', 'Written and Directed by Rob Reese', 'The Science Fiction Parody Adventure 

Keanu Reeves Saves the Universe is a twisted, bawdy, silly, romp through your favorite science fiction tales where time isn''t the only thing that''s warped!  This raucous, irreverent satire illegally marries Star Trek, Star Wars, and The Matrix to Laugh-In, South Park, and The Marx Brothers.
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('61', 'The Forever Waltz', 'By Glyn Maxwell, Directed by Elysa Maden', 'A man arrives in the underworld in search of his love, only to find a mysterious guide who may – or may not – be able to help him.  Passion, retribution, fate and forgiveness collide in this contemporary take on Orpheus.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('62', 'Town Attorney General Meeting', 'Carl E. Person, Attorney at Law', 'Failure of the U.S. Government to Enforce the Nation''s Antitrust Laws Has Created Globalization (and Resulting Theft of Trillions of Dollars from the American Public), and the Town Attorney General Can Be the Only Institution to End the Unlawful Practices

The Constitutional institutions, with their alleged checks and balances, are not working because the elected and appointed federal officials are not enforcing the nation''s laws against the multinational corporations, thereby allowing them to get away with stealing hundreds of billions of dollars (or is it trillions of dollars) from the American people, driving legitimate business competitors out of business, and destroying high-paying jobs.
The Town Attorney General Should Become, in Effect, a Law-Abiding "Godfather" for the Americans that Have Lost Their Property, Political Power and Position

Please join us as the staff of the Town Attorney General to take back our country!', 'Set Design');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('63', 'Coole Lady', 'Written and directed by Sam McCready,', 'A one-woman play performed by the celebrated Joan McCready of the Belfast Lyric Theatre. COOLE LADY is an entrancingly human portrait of larger-than-life Lady Gregory, the Irish playwright, folklorist, and political firebrand whose patronage of Yeats and founding of the Abbey Theatre launched a literary renaissance in Ireland. Lady Gregory''s public confrontations, numerous setbacks, and triumphant role in renewing a vanishing culture embody the sacrifice and indefatigable will that underlie all great art. Her story is that of Ireland itself in its struggle to preserve a national identity.www.handcartensemble.org
', 'Vocalist');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('64', 'Netro', 'by Neta Pulvermacher', '7 dance-theatre works
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('65', 'Murder in the First', 'By Dan Gordon, directed by Michael Parva', 'Based on actual events, and adapted from the motion picture of the same name, MURDER IN THE FIRST is the story of a passionate, young attorney who must prove that one criminal''s cruel treatment during three years in Alcatraz turned him into a vicious killer.  Through his defense, he uncovers the surprising truths that ultimately lead to the closing of the most notorious correctional institution in human history
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('66', 'Les Belles Soeurs (The Beautiful Sisters)', 'by Michael Tremblay, directed Deb Guston', 'This rarely performed modern comedy classic is set in the early 60s.  The main character, a working-class housewife, has won a million trading stamps in a contest.  Family, friends and neighbors come together for a book-stamping marathon – bitter jealousies, parochial frustrations and personal emergencies make for a raucously hysterical and poignant gathering.



', 'Producer');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('67', 'Bite', 'by Suzanne Bachner', 'What if your dentist had ultimate power?  Not just over your teeth - but over you?  He could tell you to sit stand, roll over.  How to talk, how to act ... what if he tied you up, smacked you around and then gave you a root canal?  Sounds like a nightmare...

What if you could take revenge on your dentist?  See him whipped, beaten and humiliated into submission?  Sounds like a dream come true...

Welcome to the world of BITE. Dig below the veneer of a sterile 5th Avenue dentists'' office and explore the dark cavities underneath. You may not find what you expect. Sugary sweetness.  Exquisite agony. Blood. Enamel. Leather. Stainless steel. Now spit.

You, the audience, will have the unique opportunity to "choose your own adventure" and discover as much or as little as you like in this strange world.  And ask: how well do you know your coworkers?  Your friends? Yourself?  For this play, you''re in control - but in your life, who''s
controlling you?  Be careful, you won''t be able to stop with just one Bite.
', 'Kids');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('68', 'Perseus', 'Directed and adapted by Ellen Stewart', 'PERSEUS - loosely based on excerpts from Ovid, Hesiod and Apollodorus with additional text by Ms. Stewart - is the often-told, but rarely-performed saga of Perseus the son of Danae and the god Zeus - who slew the serpent-headed Medusa and married the beautiful maiden Andromeda after saving her from a sea monster.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('69', 'Tonylust: The Broadway Bloodbatch of 2006', 'David Bell', 'Producer Leslie J. McMahon wants another Tony and she''s gonna get her Tony and no one is going to stand in her way!  This long awaited sequel to BERNADETTE AND THE BUTCHER OF BROADWAY pits producer against producer in an epic battle royale to secure the Tony Award for Best Musical. No Tony voter is safe as simple luncheons of the past have given way to press conferences, television commercials and mudslinging of the lowest degree.
 
', 'Solo Performance');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('70', 'Forest Blue', 'written and directed by Sarah Doyle', 'FOREST BLUE: a place to bask in the sun, a place for childhood explorations, to fantasise, a place in the last hours of a life that ends and then keeps going.

On a secluded beach in Tasmania, two disturbed sisters, and a de-toxing boyfriend set up camp, and await the arrival of their dear friend Heather, a hiker already reported as missing. Girly, Sissy and Scotty have made little preparation for their excursion, lacking the rapport and equipment to function in this increasingly hostile environment.

Night falls, and Heather has not shown up. Meanwhile, Sissy has attracted the attention of James, a pornographer living in exile in a shack provided by his lawyer.

This transient group share sexual dysfunction, preoccupation with the past, a fear of the future, and become locked in an increasingly desperate attempt to find fulfilment in the 
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('71', 'Co-op', 'A Comedy of Epic Pretensions', 'In the dark boiler room of HouseProud Towers -- a co-op on Manhattan''s Upper West Side -- a boy is raised in secret.  He is heir to a heroic legacy - to be president of the board.  Rising to the challenge of his awesome responsibility, he leads a mighty crusade against evil, corruption, mildew, and poor building finances.  His enemies are many: Trump-bewigged developers, spurned board members, and a gum-smacking, faithless wife.  Will he conquer?  Will HouseProud Towers survive?<p><p>Featured in the New York Times, May 29th, 2005. See reviews, below.<p><p>This musical farce is written and directed by John Cecil and produced by PraHaHa, who brought you last year''s "Volcano." It features a cast of eight.  For more information on the show and the cast, call 646-240-5732.<p>', 'Kids');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('72', 'Knock On Wood', 'Written and performed by Samuel Calderon', 'A one-man show about Calderon''s experiences as a combat solider in the Yom Kippur War, the special friendship he developed with another soldier, his ability to show empathy towards all soldiers including those on the "enemy" side and his process of healing.
', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('73', '''One Wednesday at West Haddam High''', 'by Adam Szymkowicz, by Adam Szymkowicz', 'A dark comedy about a high school in a small town. 

The school chef is plotting. The principal is dishing out Christ. Billy is in love with his teacher. 
Sally has challenged Jeanie to a knife fight.  Welcome back to High School.
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('74', 'Warhol', 'Directed by Gretchen Van Lente', 'Before the nose job and legal name change, Andrew Warhola was a sweet gifted boy who loved his mother. Society would love to believe he was a sex-obsessed, druggie, party-hopper. But with pop icons, the truth doesn''t really matter, does it? In their latest puppet-theatre piece, Drama of Works probes into the double life of this consumerist icon, where a soup can plays his mother and his life is literally boxed up into his signature Brillo Pad 
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('75', 'Damaged Dames', 'Todd Michael Directed by Neil Sims', 'the most elaborate "guys dressed as girls" drama/comedy of the season. "Damaged Dames" is a lunatic parody of the 1930''s "exploitation" films about the tragic pitfalls of commercialized vice. It''s a collage of movie references, taglines, and cross-indexing of this film genre. It''s the Carol Burnett Show mad movie spoof meets Charles Busch!
    The show''s concept while provocative maintains a level of innocent humor, it is what every history buff and classic movie buff will want to see this May, of course, with the addition of the 1930''s sex appeal. 
   This is the second in the line of 1930''s parodies, that author/actor Todd Michael has written over the last two years. "Damaged Dames" follows the "all-time hilarious" comedy about the 1930''s era, "Bad Dames Go to Hell", which gave a whole new meaning to "the age of prostitution", honor, and respect for friendship. However, according to Michael, "Damaged Dames" is even more elaborate, creative, and is truly a sensational nerve shocker! ', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('76', 'Henry V', 'by William Shakespeare', '1414; England''s Henry claims France and its Queen. Battles ensue, without further ado, Henry pitches his woo. Fiery stuff. (And they called him the Cold Bath King!)  

Fight direction by Ray A. Rodriguez
Costumes by Marie Suissa
Music by Luke Francis
Directed by Ted Minos
', 'Festival');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('77', 'The Waltz of Elementary Particles', 'By Jessica Lanius', 'In The Waltz of Elementary Particles, Jessica Lanius directs and choreographs a cast of actors into a devastating and fragmented world consumed with video screens, instant gratification, and personal space. Lanius'' physical interplay is a multi-media collage that combines the work of videographers Alexander Bruehl and Kristofer Updike, with the improvised music compositions of John LaSala. 

Playing in repertory with Theatre Lila''s JULIE.', 'Dance');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('78', 'Homeland', 'by Gene Ruffini', 'A play about America in the near future under a repressive regime
', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('79', ' WHY’d Ya Make Me Wear THis, Joe?', 'by Vanda, directed by Steven McElroy', 'A script-in-hand workshop, with a brief discussion after each performance. Come and be a part of the development of this new play.', 'Lesbian+Gay');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('80', 'Messages', 'JOHN FORD NOONAN''S NYC PREMIERE', 'Remember when there was only message MACHINES? No? See what happens in 1980s Manhattan, when *69 was just a pie in the sky.  
See the New York Premiere of John Ford Noonan''s MESSAGES 
Directed by Erin Woodward 
Starring: Flint Beverage, Jennifer Earhart, and Kristen Sargent.  
Featuring: Sarah Bell, Rashad Edwards, and Erin Woodward. 
', 'Lesbian+Gay');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('81', 'The Mermaid', 'by Mark Finley, directed by Barry Childs', '1962: Judith begins her career as an actress at a college in Indiana. 

1988: In Manhattan, Martin and his partner Ken prepare to adopt a child. Telling both stories simultaneously, The Mermaid reveals how the actions we take influence people we may never know.
', 'Musical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('82', 'Hamlet', 'by William Shakespeare', 'Stages of Learning presents the fifth graders of PS 6 in Manhattan in an abridged version of Shakespeare''s <B><I>Hamlet</I></B>.  The company brings teaching actors into New York City public schools for up to 20 weeks each year.  Working closely with classroom teachers, the children learn their regular curriculum through theater.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('83', 'The Maiden''s Prayer', 'Nicky Silver', 'Prostitution.  Dueling Diva Sisters.  And Just a li''l bit of nudity.  Follow the lives of 5 characters cosmically intertwined by love, lust and addiction.  All eyes are on handsome Taylor.  Two sisters battle over his affection while his gay best friend pines over this and other unrequieted love.  Watch comic reality unfold as people seek the love they want, yet put up roadblocks to prevent it. ', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('84', 'Old Man Pete', 'by Randolph Edmonds', 'After a general concensus, the Collier children decide to move their aging parents to Harlem from rural Virginia.  The children are confronted with the realization that their parents may never adjust to "city life" as they had hoped.  Nonetheless, the plot thickens as tempers flare against a backdrop of  1930''s signature music and dance.', 'Dance');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('85', 'The Territory', 'Two One Acts by Tanya Krohn', 'These two fables of suburbia feature an alarm company salesman, an air force wife, and a man whose junk mail has begun stalking him.  <p><p>The cast includes Nancy Jacobs, Rob O''Hare, Sheila Bandyopadhyay, Simon MacLean, Toby Lawless, Sandie Luna and Jennifer Lee Mitchell.  Sheila Bandyopadhyay and Dean Parker direct.<p><p>THE TERRITORY marks the second production of Groundplay, a theater company dedicated to creating work that is physical, socially relevant, and infused with a humor that produces both laughter and thought. <p>', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('86', 'What Women Talk About', 'Unscripted. Unpredictable. Unbelievable.', 'Ever wonder what women really say when men aren''t around? Wonder no more.

Unscripted. Unbelievable. Unpredictable. This unscripted weekly episodic show follows the women from dating to divorce, from politics to the proper way to cheat on someone. These women talk about anything – and everything in between!

The same creative force that brought you "Chick Flicks" and "Sexy, Sane & Single" presents Brenna Palughi as Sophie, Mardi Sykes as Kimmi, Katharine Heller as Sara, and Lauren Seikaly as Bonnie. Directed by acclaimed duo of Wayne Parillo and Hugh Sinclair.', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('87', 'The Persians...a comedy about war with five songs', 'Based on the play by Aeschylus', 'The Persians were the most powerful empire the world had ever seen. 
The Persians'' army was the biggest war machine ever assembled. 
The Persians marched off to destroy their most hated enemies. 
The Persians lost the war and the world. 

The revolution is about to begin...let us entertain you!

www.waterwell.org', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('88', 'Ren Ah, Ren  (you, O You Humans)', 'adapted and directed by Joanna Chan', 'Based novel by Dai HouYing, about the excesses of the Chinese Cultural Revolution.

Even those who lived through China''s Great Leap Forward (1958-1961) could not have anticipated what would come next.  The Great Leap Forward was an extraordinary scheme conceived by Chinese Communist Party Chairman Mao Zedong to accelerate dramatically China''s economic development.  It led to an estimated 30 million deaths by starvation. 

Using a handful of fictional characters based on her own experience, Ms. Dai (1938-1996) allowed a glimpse into the harrowing journey of the privileged class (the intellectuals) from youthful conviction and unquestioning commitment to Mao''s vision of the utopia, through, in the author''s own words, "the painful groaning of a twisted soul, and the sparkle of a living spirit in darkness," to a terrifying awakening to their own humanity."  

The play views the Cultural Revolution through the eyes of three people in a love triangle: two men, Ho and Zhao, and a woman, Sun.  Although they have the bonds of love and friendship and are united in the struggle for a new China, the Maoist system forces them into positions against each other in a sequence of horrible betrayals.  
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('89', 'Siren Says', 'by Ronnie Koenig', 'Spend the night with amNewYork''s "Siren Says" columnist Ronnie Koenig, who''s run around town this past year getting the scoop on the sexiest goings-on in the city.

Tonight Ronnie shares many of her funniest column exploits, which include how she found herself in a porn video booth and ruminations on Vincent Gallo''s private parts. Not since Katie Couric''s sit-down with junior high students has there been a smuttier, more gratuitous, and informative event in the world of sex!

This is a staged reading

Calls for tickets taken 11:00am-6:30pm daily.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('90', 'Boundless as the Sea', 'Directed by Marc Silberschatz', 'Productions of 
The Tempest & Twelfth Night 

Two of the Shakespeare works – which deal dramatically (Tempest) and comedically (Twelfth Night) with the idea that to love someone, you must be willing to give something up.  

In THE TEMPEST, Prospero realizes that he must not only let Miranda go because he loves her, but must give up his quest for vengeance and the safety of the island he has lived on for the past sixteen years and return to the world.  

In TWELFTH NIGHT, we watch as desperately lonely characters hilariously give up their identity (Viola), dignity (Malvolio and Olivia) money (Sir Andrew) and anything else they can find to try to be with the person they love.  By the end of both shows, the characters are happier, or at least wiser, as is the audience who has shred with them the experience of learning what it means to love another person.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('91', 'Uncommon Women and Others', 'Wendy Wasserstein', 'A memory play of eight women''s personal growth within their community at Mount Holyoke. Destined to reach their own highest potential they learn best from their own precious friendships.', 'Classical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('92', 'The Devil Winks (To Be or Not to Be on Avenue B)', 'written and performed by David Sirk', 'Whether or not you are  a native New Yorker, you can''t help but be fascinated with the unique history of  the East  Village. Now a trendy  neighborhood, the area formerly known as Alphabet City was once a den of drug  denizens and a hipster hotspot for restless artists trying to express themselves  in the turbulent decades leading up to the 21st century.

Actor-writer David Sirk brings his own retrospective to life as he relives his youth in the  neighborhood in his solo show "The Devil Winks," presenting a travelogue back in  time for those who lived it and those who wish they did. 
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('93', 'The Republic of Poetry', 'conceived by Barbara Vann', '"THE REPUBLIC OF POETRY" comprises the work of 11 poets, each of whom has written a short verse play especially for this project ranging from 2 to 20 minutes in length. 

Some of the highlights: 

Filip Marinovich''s "Salient Mourners," in which the Army presents its official policy on fallen soldiers in Iraq with doublespeak and euphemism

Denise Duhamel''s "Pituitary Theft," which is composed entirely of fake English subtitles from Hong Kong movies

Harry Matthews'' "Trial Impressions," a suite on the changeability of love. 

The poets who''ve contributed to the evening include Martin Espada, who has been called "the Latino poet of his generation" and whose latest collection of poetry received the Paterson Award for Sustained Literary Achievement and was named an American Library Association Notable Book of the year. His poems have appeared in the New York Times Book Review, Harper''s, The Nation, and The Best American Poetry; Arnold Weinstein, librettist for the opera "A View From The Bridge" and lyricist for William Bolcom''s "Casino Paradise"; Harry Matthews, whose latest novel "The Journalist" was acclaimed by the New York Times and Time Out; as well as Bayard, Denise Duhamel, Vincent Katz, Roy Lisker, Filip Marinovich, Simon Pettet, Miriam Sagan and Bruce Weber. 
', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('94', 'Tara''s Crossing by Jeffrey Solomon', 'directed by Steve Satta', 'A play about political asylum for Lesbian, Gay, Bi-Sexual, and Transgendered Refugees

Since 1994, a small but significant number of refugees have been considered for political asylum in the U.S. if they can prove they were persecuted on account of their sexual orientation, gender identity or HIV status. Tara''s Crossing recounts a transgendered asylum-seeker''s remarkable flight from Guyana and her uphill battle to prove her claims of persecution from within the confines of U.S. Immigration Detention. The play is one of the first ever to deal with the subject of political asylum for sexual minority refugees and was inspired by interviews with asylum-seekers from around the world.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('95', 'The Scaffolding', 'Music and Libretto by Martin Halpern', 'A Chamber Opera in Two Acts
Freely based on Henrik Ibsen''s play The Master Builder

In a plot packed with psychological and moral ambiguities, a famous aging architect is confronted by a mysterious young woman out of his past.  Their encounter builds through a series of emotional twists and turns to a climax in which he is rejuvenated, but at the cost of his life.  Over all the action hovers the question: has she come to save him, to destroy him, or both at the same time?


', 'Dance');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('96', 'Promised Land', 'by Sam Riley, directed by Paul Kropfl', 'Promised Land is a tragic love story set in the present day in a small town south of the Mason-Dixon line.  Hunter, a waitress at Applebee''s who dreams of touring the country on a never-ending road trip, meets Hank, a simple, emotionally wounded construction worker, at the Palace bar.  As their romance evolves, we come to understand their desperation and the struggles of the families they live with.  Hunter sleeps on a cot in the living room of her older sister Mary''s house with Mary''s boyfriend Mike and their infant daughter in a family situation going nowhere.  Mike has lost his job and, pressured by Mary to support their family, enlists in the military.  Hank lives with his alcoholic, abusive father, Wayne who is unable to come to terms with his own failings and rails against Hank for straying from the path Wayne raised him to follow.  Hank and Hunter plan to escape but are trapped in an emotionally vacuous landscape and subject to the heartbreak of hope and alienation.
 
"I wanna know America, Hank," expounds the young protagonist Hunter.  "I wanna know it so deep that when it starts to show its ugly face I can rest knowin'' I''ve seen its heart."
 
Promised Land is also celebration of the role of the artist, the free-thinking, free-feeling individual who uses his medium to hold a mirror to contemporary society.  In the tradition of Sam Shepard and Clifford Odets, Sam Riley writes about America out of conviction for the exhilarating potential of the theater as a conduit for social change.  Inspired to counteract the transgression of our societal values from rugged individualism to complacent consumerism, Riley lays a bold path toward serious examination of American culture with Promised Land.

', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('97', 'Project Playwright...The Show', 'Directed By Will Warren', 'MADAIR Productions Presents a collection of previously unproduced short plays by fresh, talented playwrights from around the country.  Together they create a study of varying degrees of dysfunction in humanity: from the heartfelt to the absurd, revealing inner demons, and exploring tabloid fantasies.

Featuring Plays by; Jacob Burstein-Stern, Michelle Carter, Rich Frost, Craig McNulty, and Adrian Quihuis.', 'Solo');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('98', 'As You Like it', 'by William Shakespeare', 'Meet us at the entrance to Central Park at West 103rd Street and Central Park West.

No tickets or reservations are required—just show up!  And it''s FREE  (really!)

Take the subway (B or C to 103rd Street) or bus (M10) right to the park gates.

This is a moving performance!  Every 10 to 15 minutes the production picks up and moves to a different location. Wear comfortable shoes or sneakers. The show is wheelchair accessible and perfect for young children.

Special Event!!!
Picnic-in-the-Park
Benefit
for New York Classical Theatre
Saturday, June 18th, 5:30pm

To order picnic baskets, call PicNic Café at (212) 222-8222
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('99', 'Detour', 'written and performed by John Tedeschi', 'DETOUR reflects the ever-changing-good and not-so-good circumstances that weave all people''s lives.  We strive, once we are able to motivate ourselves, to make one step in front of the other but frequently those strides must go in other, often uncharted, directions...This performative work uses original and covered music ranging from Scorpions to Sondheim, stand-up to Socratic stoicism and sex to civility to tell the story of unexpected change in spite of how securely one may try to nail down the yet to come.

Musical direction by Brenda Bush
Music consultant Mitch Kaplan

general admission tickets and reservations through www.theatremania.com or 212-252-3204

DETOUR is part of The CARNIVAL OF CULTURE presented at the Access Gallery from June 20th – July 10th.   The CARNIVAL OF CULTURE will feature art exhibitions by Olan, Bill Sharp, Greg Zukowski, Robert W. Richards, Bradford Noble, Karen Lowry, Manu Saluja and Danielle Fonseca.  Fashion shows by Philippe and David Blond and Keanan Duffty.  Music by Keyth Lawrence, Ari Gold, Brenda Bush, SUBSTRIKE, Adam Joseph, Lisa Heffter and the cast of PERMISSION.  Dance by Paula Plessas, Ann Robideaux and Julie Troost.  Readings by David Parr and Michael Griffo and photography and film presentations by Tommy McCall and Adam Stroncone, Mike Lane and Steven Kijak.  

', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('100', 'I Found Her Tied To My Bed', 'written and directed by Jeff Tabnick', 'I FOUND HER TIED TO MY BED
 
(presented as part of The Moral Values Festival)
 
At Evergreen Manor Nursing Home, the hours are long, the staff is underpaid and the occupants are easy to kill.  When a reckless coworker intrudes upon Beth''s solitary life, Beth becomes infatuated and goes to extremes to understand her. But understanding does not necessarily produce a healthy relationship—sometimes it only produces corpses.  A dark comedy.
', 'Musical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('101', 'Merrily We Roll Along', 'By Stephen Sondheim and George Furth', 'New Yorkers know that starting out in this city of 8 million stories is exhilarating, scary, and an experience never to be forgotten. Even jaded natives remember the feeling of finding their first apartment, getting their first big break. For those who''ve never seen Stephen Sondheim''s tribute to starting out in the Big Apple, "Merrily We Roll Along" will resonate...whether you''re 18 or 80. 

Although a critical and commercial failure when it opened on Broadway in 1981, "Merrily We Roll Along" was delicately retooled for the 1994 revival and went on to win the 2001 Olivier Award in London. The original production was staged at the Alvin Theater and directed by Hal Prince. The 1994 streamlined version was a sell-out production staged at the York Theatre Company and directed by Susan H. Schulman. 

"Merrily We Roll Along" begins in California in 1976 and rolls scene by scene back to 1957 as Frank, Mary and Charley trace the roots of their friendship. Along the way, they struggle with issues of the allure of money-grubbing Hollywood versus the collaborative art of writing Broadway musicals; remaining loyal to family and friends while still watching out for yourself; accepting that love and loss and growing up take their toll on everyone differently. By the end of the play, the three friends find themselves at age 20 on the Upper West Side of Manhattan and at the beginning of their illustrious careers on Broadway and in Hollywood. 

George Furth wrote the book of the musical, drawn from a Kaufman and Hart play of the same name. Uplifting numbers include "Old Friends," "Not a Day Goes By" and "Good Thing Going."', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('102', 'The Real Inspector Hound', 'Tom Stoppard', 'This play within a play spoofs the Agatha Christie type whodunit by contrasting reality and illusion with clever wit and humor.  A performer''s disability will be incorporated as part of the character, bringing an added dimension to this satirical murder mystery without affecting its plot and giving disabled performers the opportunity to express themselves in roles that are not "written as disabled". ', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('103', 'When Silence Explodes: Fetus', 'Rada Angelova', 'Can you hear them? Two girls who are just out of high school talk about...their dreams. One wants to be the first white female MC to earn the respect of the biggies. The other, she just wants to be American. But what exactly does "American" mean? Miss Prime educates Krisi in When Silence Explodes: Fetus. 

whensilenceexplodes.com', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('104', 'La Nena Se Casa', 'By Carlos Ferrari, Directed by Emil Cruz', 'CHAS presents  " La Nena Se Casa" (black humor two acts comedy) by Carlos Ferrari, The social and economical problematic of a middle class family faces in San Juan, Puerto Rico. After a series of unexpected events, Juan (father of three young and adults daughters - Yanisoria, Brifimar, Auriler) fumes into different scenes unveiling the real situation of his family. At the end,Ramonita''s memories (Juan''s abnegated wife) guide us through flashbacks that put together the dramatic but also comic ending.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('105', 'Four One Legged Men', 'Written and Performed by Gary Corbin', 'A bold, audacious, and humorous depiction of four distinct amputees from different backgrounds, seasons and eras. This unique theatrical experience consists of four vignettes: " A day in the life of Jamie Prince" - a writer who visits his dying foster grandparent who is in a nursing home in the Winter of 2005; " Rainbow" - a father in a visitation rights battle in the Spring of 1959; "I''ll Betcha That!" - a gay male on his way to a Fourth of July party in the Summer of 1979, but falls and breaks his artificial leg; "Waiting for Oz" - a delusional Vietnam veteran on a psyche ward after returning from the battlefield in the Fall of 1969. The final vignette is performed without an artificial leg. A critic once wrote: "A one-legged man dancing to Proud Mary by Ike and Tina Turner? It''s to Corbin''s credit that he can make a seemingly audacious act seem anything else but!"', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('106', 'The Girlhood of Shakespeare''s Heroines', 'by Don Nigro', 'The Girlhood of Shakespear''s Heroines consists of five monologues uniting to create one interconnected piece, much as Shakespeare''s five acts create one play.   In these five monologues, Don Nigro allows five young women, characters from Shakespeare''s plays or significantly influenced by those same characters, to discuss as never before their views on love, life, sex and theatre.
  
Each eloquent speech illuminates the others while remaining distinctly its own.  The ideas flow forth with a sense of urgency, eliminating preconceptions and pleading to be heard; as Don Nigro says, "The greatest act of love is to pay attention."
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('107', 'The Bigger Man', 'by Sam Marks, directed by Louis Moreno', 'Len, a former thief and all-around screw-up, has serious doubts about the upcoming wedding of his ex-girfriend.  The night before the ceremony, while sharing a hotel room with his drug addict buddy, Len is certain that something is not quite right about the entire event.  He may not be the Best Man, but can he be The Bigger Man?  Pitting urban nihilism against surban optomisism, this off-kiler love story is played out in soggy hotel rooms, with paranoid wedding guests, an aggrivessibly friendly host and uncertain danger lurking at every turn', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('108', 'Feasting On Cardigans', 'by Mark Eisman, directed by Amy Henault', 'Moths are wreaking havoc on the closets of New York. Exterminators Haff and Rose-Marie are on the front lines. Rose-Marie wants a baby and feels Haff would be the ideal contributor, but that really bugs his fiancée. A comedic Sci-Fi parable about parenthood and Mothra. "Be safe. Wear cotton."

An Equity Showcase

Part of the Sixth Annual International Theatre Festival', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('110', 'Sit-Down', 'written and performed by Desiree Burch', 'Chewing on America''s insatiable need for the rock-stardom of the self-destructive with insightful wit, Desiree Burch deciphers the desire for escape and apocalypse. Fed by the tit of television and an Ethernet umbilical cord, Burch illuminates the humanexperience according to the rules of disengagement. Through song, comedy,monologue, dance, parody and video Desiree explores out-of-body heights in the "pursuit of happiness, which is the pursuit of meaning, which is the pursuit of art, which is the pursuit of pursuit."', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('111', 'Twelfth Night - Or What You Will', 'by William Shakespeare', 'This production, set between the two world wars in the mythical land of Illyria, follows Feste (the flyer), Viola (the flapper), Malvolio (the malcontent), Orsino, Olivia (O, whose woes never cease to flow) Sebastian and a swashbuckler, and, of course, Sir Toby Belch and friends as they face love, death and growing up with music, gender-bending mistaken identity, and comedy.  With an hour and forty minute run time, this is the perfect way for folks of all ages to spend a brief interlude on a July day.  
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('112', 'QUICKTHINKING! Improv presents...', 'nIgHt oF tHe qUiCkThInKeRs!', 'Short and long form improvisation with the QUICKTHINKERS!  Showtimes: 7:00 & 9:00pm  Tickets only $10!', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('113', '21 Stories: A Broadway Tale', 'G.W. Stevens', 'Billy Youngblood is a knock around soccer player from Northern England with a passion to make it as a Broadway star. Margaret Evans is a tomboy from small town Texas with delusions of finding her father. These two collide in The Big Apple and together they embark on a journey in pursuit of their dreams. Billy to join the perfect musical and Margaret in search of hope, friendship and love... and what they find isn''t always something to sing about.

It''s a Romeo and Juliet story set against the backdrop of some of the Mega musicals in the 80''s. How far would they go and what would be the ultimate price. Its an emotional journey of fun, drama along with a little bit of toe tapping. 

Audiences can expect to laugh, cry and sing along with some of their favorite shows as they follow this energetic compelling story of Billy and Margaret accompanied by a unique blend of a Greek chorus. In 21 STORIES the audience will see the impact of holding on to a dream.

', 'Comedian');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('115', 'The Three Musketeers', 'adapted and directed by Ted Minos', 'Inwood Shakespeare Festival brings Romance & Swashbuckling to the great outdoors! Need we say more? Remember the Beatles; see them while they''re free! Get those up-front seats (grass) "every man/woman for him/her self"! 

Fight choreography by Ray A. Rodriguez, Costumes by Marie Gallas-Suissa. Music by Luke Francis, Technical Director Catherine Bruce. Adapted and directed by Ted Minos. Produced by Moose Hall Theatre Company

Photo by Minos:Left to right:
Aaron Simms (Porthos), Ray A. Rodriguez (Athos), E. Calvin Ahn (Aramis), Michael M. McGuire (D''Artagnan)

', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('116', 'Evensong', 'by Mary Gage, directed by Lewis Magruder', 'Evensong is based on the poignant memories of six Americans over age 80 in Midland, Michigan whose life stories are woven into a text that resembles jazz music.
', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('117', 'Apathy: The Gen X Musical', 'The HAIR of the 90''s that bit you!', '"Theatre Seldom digs this deeply into youthful alienation...A Powerful Chord" -Jack Zink, Sun Sentinel

"Like Fellini going on a three day speedball binge and trying to rewrite FRIENDS" -Paul Gallotta, XS Magazine 

"Wild, erratic APATHY squeezes sparks from raw, dead-on look at Generation X" - Christine Dolan, Miami Herald 

Follow the wacky adventures of a drug dealing vamp and her friends (a manic slacker, a goth chick, a party slut, a closet case, and her cuckold boyfriend) as they smoke dope, trip on acid, undermine authority, and treat anything "PC" with insane irreverence! 
F*CK RENT!

Words & Music by Mickey Zetts
Directed by Paula D''Alessandris
The Cast features Fiona Choi, Ethan Gomez, Samantha Leigh Josephs, Ryan G. Metzger, Matt Miniea, Duncan Pflaster & Sami Rudnick', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('118', 'Good Fences Make Good Neighbors', 'By Adam Klasfeld', 'One Armed Man presents the world premiere of <a href="http://www.onearmedman.org" target="_blank"><I>Good Fences Make Good Neighbors</i></a>, a tragicomedy by Adam Klasfeld, at FringeNYC.  Set in a fictional town in Arabia, the play follows a middle-aged writer who gets shot in the arm outside of his house, leaving him an amputee.  But nobody believes that his arm is missing, fracturing his entire reality.  His only source of safety from future attacks comes from an old stone wall supervised by a short but crafty elf, whose job is to tear it down. An oblique commentary on the Israeli-Palestinian conflict, it examines how the fear that terrorism generates can be almost as debilitating as its carnage.

Set design generously provided by <a href="http://www.artistspaintforpeace.org" target="_blank">Artists Paint for Peace</a>.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('119', 'The Curate Shakespeare As You Like It', 'By Don Nigro, Directed by Sam Reich', 'The Curate Shakespeare''s As You Like It follows a troupe of haphazard, 
energetic Shakespeare performers as they try whole-heartedly and half 
successfully to perform the bard''s best comedy.  
Performed by the resident improv troupe of Mike Nichols'' New Actors Workshop and 
directed by Executive Producer of www.DutchWest.tv Sam Reich.
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('120', 'Billy Sleepyhead', 'A Sci-Fi Musical', 'Something terrible has happened to young Abilgail, a.k.a "Billy".  A horrible shadow of a person has stolen something very valuable to her and it looks like she may never wake up.  It''s now up to her brother and sister to journey a vast distance and face that most horrid villain in order to save their darling "Billy Sleepyhead".

book & lyrics Webb Wilcoxen, music Webb Wilcoxen and Arthur Bacon, director Jill DeArmon

Featuring: Alex Flores, Meghan Lynch, Elijah Martinez, Andrew Mayer, Kiko Morini, Danielle Piacentile, Gabrielle Piacentile, Kristin Piacentile, Lindsey Rose, Elanna White & with Charles Goforth

set design Joe Powell, costume design Meghan Healey, lighting design Where
stage manager Aime Kelly, assistant director Jamie Klessel

producers Bryan Billig, Heather Morris, John Richardson & Jinn S. Kim', 'Comedian');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('121', 'Cemetery of Lips', 'by Nancy Ancowitz', 'After sold-out performances in the New York International Fringe Festival, Nancy Ancowitz''s play, "Cemetery of Lips," was selected in to the Six Figures Theatre Company Artists of Tomorrow Festival. Performances are on Saturday, October 1 at 7 p.m., and Sunday, October 2 at 5 p.m. at the West End Theatre at 263 West 86 Street, 2nd floor.

"Cemetery of Lips" is the story of a woman who thought she had nothing to say. With her signature brand of macabre humor and her deliciously surreal language, playwright Nancy Ancowitz lures us down the alimentary canal to a reservoir of unspoken thoughts and desires. Here amid her swallowed words, our intrepid heroine sets off to reclaim her missing truth. Fearless in its message, the play combines thrillingly poetic riffs, deliciously surreal rants, and a powerhouse performance with hand-drums and violin. Expect a wild ride. Bring your lips. Bring your chap stick.

Nancy Ancowitz is a nationally recognized marketing strategist and coach who helps people express themselves with confidence. She wrote "Cemetery of Lips" to mark her return to a creative life after a long stint in the corporate world. Originally developed as part of the Artists-In-Residence Program at Makor (West Side Center of the 92 Street Y), "Cemetery of Lips" was selected into the CUNY Human Rights Theatre Project. Ms. Ancowitz''s full-length play, "Hablo, Diablo" (translation: "I Speak, Devil") enjoyed sold-out staged readings at Makor in May 2005.

Performer Jaye Austin Williams is an actor, director, playwright, teacher, and novelist. Her critically acclaimed performance of Suzan-Lori Parks'' one-woman play, "Pickling," was presented at HERE, Joe''s Pub, the Mint, and at the Cherry Lane. Jaye''s work has been seen on and off Broadway and regionally. Her first novel, "Jasmine," will be published by HarperCollins in the fall of 2006.

Director Barbara Rubin made her Off-Broadway debut last season with Antigone Project at The Women''s Project, and she was the associate director on the recent Broadway production of "A Streetcar Named Desire." Previously on Broadway she was assistant director on "The Dance of Death" and "The Elephant Man." She was also assistant director to Athol Fugard on "Sorrows and Rejoicings" at McCarter Theatre and at Second Stage in New York.

"Cemetery of Lips" is an enchanting spoken word performance. A percussive dream with a lot of surprises and a little bite....

By: Nancy Ancowitz
Directed by: Barbara Rubin
Starring: Jaye Austin Williams
On drums: Anoush
On violin: Joyce Chen 
Assistant director: Greg Cicchino
Production stage manager: Jamie Rog
Costume designer: Anoush
Set designer: Michael V. Moore
Lighting designer: Jesse Belsky
Associate producer: Samuel A. Morris
 
Graphic design: Liz Kinnmark
ekinnmar@andrew.cmu.edu
', 'Author');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('122', 'kamp NYC presents "Break Through"', ' Written by Mike Turner', 'Hello, I''m Joe Loera the Founder/Producer of kamp NYC, an intensive one-of-a-kind Broadway experience, started three years ago to train the most talented young performers in the United States and abroad. With the assistance of the best instructors in New York City, these twenty young talented individuals (12-17 yrs) have a life changing opportunity to live, breathe their passion and perform in an original off-Broadway show. This seven day intensive helps participants learn important techniques, gives them vital experience, and most importantly, gives them a first-hand realization of the pressures and obstacles of performing in New York City. These kids, from diverse backgrounds, make life long friendships and come together with the same dream of making it on Broadway.<p><p><p>

Directed by Kate Marks,

Vocal Direction by Richard Lissemore,

Musical Direction by Robert Grusecki,
  
Choreography by Joey Dowling

and Produced by Joe Loera<p><p><p>


Please come out and support the future of the entertainment industry!<p>
"They will inspire you..."', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('123', 'Feud: Fire on the Mountain', 'Written and Directed by Creighton James', 'Feud: Fire on the Mountain begins at the end of the Civil War when the lynching of a returning Union soldier sets off a private war between two Appalachian families.  The classic, true story of the bloodiest, most notorious feud in American history is reinvented with a dark comic flavor. Underlying tensions explode between the Hatfields and McCoys, building to a provocative, gripping climax. What happened to Love Thy Neighbor?', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('124', 'Wonder GirlZ', 'directed by Brian Thomas', '"Pussycat Dolls meets Charlie''s Angels" is the best way to describe Wonder GirlZ, an off Broadway, song and dance show with a theme that empowers women.  The cast is made up of New York''s - sexiest and best - female and male performers communicating the need for more feminine energy to be in power in the world. This show is thought provoking as much as it is sexy and fun.  Perfect, for a couple''s night out- it has the sex appeal that the men will like and the storyline that women will love and appreciate. Songstress'' vary from week to week. 
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('125', 'Midnight', 'written and directed by David Epsiten', 'Set in the 1950''s atop the Ritz Carlton Hotel, Midnight revolves around an egomaniacal Hollywood director who is desperately trying to salvage his flagging career, while is long-suffering Girl Friday does her best to keep her temperamental boss unaware of just how precarious his situation is.  To make matters worse, a humble writer from the Bronx breaks into their suite to avoid Jewish mobsters who require payment of a loan by midnight – or else.  A British butler, doltish bellhops, a crass producer and his ditsy girl all converge on the scene in a farcical roundelay that is sure to put a smile on your face.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('126', 'Summer Series', 'WWW.ONTOLOGICAL.COM', 'Replacing the OBIE Award Winning Blueprint Series with a 5 week festival that runs from July 27th to August 27th.  The 5 pieces range from static banality to bizarrerie each creating their own unique environments using analog and digital media to push the boundaries of expression and communicate their own inimitable vision of the world. For schedule info go to www.ontological.com  Tickets are $15 location is at St. Marks Church 131 East 10th St. @ 2nd Ave.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('127', 'Forever Foolish', 'Starring Anita Brown', 'A return engagement of the cabaret evening in which Anita Brown, New York''s newest Diva, sings spicy, saucy, sexy and serious songs 
her friends wrote...sprinkled with a few chosen words on life, love, lust, liberty and the pursuit of happiness.  With musical director Woody Regan at the piano.  Directed by Miriam Fond.  With special surprise guests.  Air conditioning and refreshments served.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('128', 'Eliza''s Windon', 'by Natalie Burgess', 'A new puppet play with music

presented by Paper City Productions in conjunction with Paddywhack Players

', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('129', 'The Geranium on the Window Sill Just Died"', 'adapted and directed by Michael Lluberes', 'A new play about a group of elementary school students who confront their teacher and transform their cold classroom into a playground for their imagination.  Based on the widely-banned, now out-of-print book, The Geranium on the Window Sill Just Died But Teacher You Went Right On by Albert Cullum, which sold over half a million copies, The Geranium Theatre Company has transformed his book expressing children''s inner thoughts and feelings into an emotionally moving theatrical landscape of music, movement and poetry, where windows open to let in paper rain, crayons color children''s faces, walls dance, and a dead geranium on the window sill comes back to life.
', 'Stage Mgr');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('130', 'A Midsummer Night''s Dream', 'by William Shakespeare', 'The Shakespeare Classic 

For information (212) 695-1596 

The fully-staged, professional production includes  8 young members of the Harlem community, ranging in age from 9 to 22, who have joined the multi-ethnic cast of seasoned actors.  The production is presented by The  HARLEM SUMMER SHAKESPEARE PROJECT as part of HARLEM WEEK.
', 'Sound');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('131', 'Gift', 'by Mark Schultz', 'The agoraphobic Sylvie is trying desperately not to celebrate her birthday.  A friend shows up with a gift she can''t refuse that promises redemption or devastation, and they find themselves in the dark sharing the same space, a few cigarettes, and the possibility of some cake.

Directed by Daniel Talbott and featuring Spencer Aste, Denis Butkus, and Chris Kipiniak.  Assistant directed by Julie Kline and lighting by Brian Roff.', 'Vocalist');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('132', 'Oh Sister!', 'Daniel Stone', 'A mystical magical story of one man''s journey from darkness into light. 
Author/performer Daniel Stone weaves a poignant and inspirational tale of memory, song, poetry and role play recounting the tragic death of his older sister and his spiritual growth that led to his final acceptance. ', 'Author');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('134', 'Galexy Video/Galexy Video 2', 'written and directed by Marc Morales', 'One hour to closing, the employees of Galaxy Video deal with 
customers seeking films like... "that movie that had that guy in it who was in that movie with that girl" ...while dealing with the everyday problems in their own lives...and now comes......Galaxy Video 2!!!

Once upon a time there was a video store & it came crashing to the ground. Now Galaxy Video reopens under the watchful eye of "The Man" with plans to franchise. Will "The Man" succeed ...or will the band of rebel-without-a-clue employees foil his corporate plan?

Both shows play in repertory
', 'Musical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('135', 'The fallen 9/11', 'by Robert Marese', 'Set on the morning of September 11, 2001, two men – a NYC Firefighter and high-powered    attorney - find themselves fatefully brought together, trapped below the rubble of one of the two towers.  Under these surreal and tragic circumstances, their dialogue leads each on a path of self-discovery and revelation.

A portion of profits will go to the "Let Us Do Good" Children''s Foundation, established in memory of Firefighter Stephen Siller.  More information on The Fallen 9/11 and "Let Us Do Good" Children''s Foundation can be found at their respective websites www.TheFallen911.com and www.tunneltotowersrun.org.
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('136', 'Homeland', 'by Gene Ruffini', 'About an America in the near future under a repressive regime.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('137', 'Macbeth', 'William Shakespeare', 'Murder and mayhem, barbed wire and bedlam, Macbeth meets the metaphysical amidst post-apocalyptic waste.  The classic Shakespearean tragedy set in future Scotland, after the plague.  The countryside has been ravaged and its people still bear the wounds of the recent wars.  A cast of eighteen conveys the contemporary concept of this play while delivering dialogue true to the original work.', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('138', 'Iphigenia at Aulis', 'by Euripidesm, adapated by W.S. Merwin', 'Iphigenia at Aulis has been described as one of the most human of the Greek tragedies. At Aulis, High King Agamemnon has gathered the greatest fighting force the world has ever seen, poised to strike at Troy.  At Aulis, soldiers gird themselves to reclaim the unparalleled beauty of Helen and win everlasting glory. At Aulis, the wind has died. At Aulis, a prophet mutters of sacrifice, and the High King summons his daughter to camp with promises of marriage to the hero Achilles.  Sacrifices will be made, marriages marred, and wars waged, upon the arrival of Iphigenia at Aulis. Written by Euripides in 410BCE and adapted with stunningly modern clarity by W.S. Merwin, Iphigenia at Aulis holds no one entirely innocent in its thorough examination of the lies we tell, the people we manipulate, and the sacrifice we make to go to war. ', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('139', 'Lady Convoy', 'by Ken Gallo', 'A play at the New York International Fringe Festival', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('140', 'Soul Searching', 'written and directed by Matt Okin', 'Searching follows a single, Jewish woman in New York City on her journey to find the perfect match, but along the way she discovers much more than just her soul-mate, she discovers her own soul.

Brenda (played by Shelley Dague) is beautiful, intelligent with a successful career, but wonders why she is still alone.   Her married friends set her up with various men within the Jewish community, however each one seems to carry a message of isolation.   Although she wants to share her life with someone, she also wants to share her life with an accepting community of people.

Music & Lyrics:   Avi Kunstler 
Book & Additional Music/Lyrics:   Matt Okin
Assistant Director:  Eytan Bayme
Musical   Director:  Yitzy Glicksman', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('141', 'The Audition', 'Created and directed by Betsy Head', 'At each night of THE AUDITION< ten actors (found in local ads and by word-of-mouth) and one lucky person chosen from the audience will perform their prepared monologue for a panel of three entertainment industry professionals (directors, producers, and casting directors) and the audience.

After the initial auditions are complete, the audience votes for their favorite performer.  The six top-ranking actors return for Act II t claim their prize – the highly coveted callback.  The night then culminates in cold readings and performances of specially crated scenes.

For the actor, THE AUDITION is a chance to hone their skills and perhaps be discovered.  For the audience, THE AUDITION provides and entertaining and insightful glimpse inside the cutthroat world of casting.  Come find out: Who will make the cut?


', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('142', 'No Boundaries', 'Written and directed by Liz Oliver', 'No Boundaries centers around Ali, an idealistic and free-spirited young white girl who is set to attend Julliard in the Fall.  When Ali auditions for an up-and-coming all-black rap group, it triggers a series of events rife with racial tension.  It also strains her relationship with her best friend Joshua – 18, black, and with his own ambitions.  As they passionately pursue their dreams, Joshua and Ali are forced to confront painful issues of identity, loyalty and race that threaten to alter their friendship forever.
', 'Lesbian+Gay');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('143', 'Bootleg Islam', 'performed by Negin Farsad', 'In Bootleg Islam, comedy  award-nominated and critically acclaimed sketch comedian, Negin Farsad presents  an unconventional perspective on her controversial homeland –  Iran. Sure women  are "second class" citizens and enriched uranium lines the streets, but boy does  this fundamentalist Muslim country make for some hilarious comedy! Drawing from her last trip to  Iran for a  wedding, Farsad combines comic monologues and impressions of family drama to  compare oppressed life in  Iran with her  own Crate-&-Barrel-accented life in  America. From  witnessing lamb sacrifices to navigating third-world toilets, she uses her  personal adventures and expertise in sketch comedy to give us a glimpse into  this misunderstood Islamic world. Her high-speed time-lapsing  montages result in an energetic look into Muslim life where she asks essential  questions like "Does this chador make me look fat?" and, "How come this How come this Muslim  country hasn''t discovered Splenda?"
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('144', 'My Super Evil Inferior Complex!!', 'Written by Steven Wiliam', 'A struggling young actor from the Bronx is battling with his evil walking and talking inferior complex that is destroying his acting career, love life, and self confidence. "My Super Evil Inferior Complex" is a new play written by Steven William that aims to motivate the audience to take control of their lives and achieve their dreams.
 
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('145', 'Not Enough Princesses', 'Adapted and Directed by Shari Johnson', 'Not Enough Princesses is a new play for children based on classic, yet not well-known, Swedish fairytales. Assorted characters are searching the forest separately for a princess, little knowing that there is only one princess at the end of their quest. On their way they meet a variety of trolls and fantastic creatures. The style and mood is inspired by the work of Swedish illustrator John Bauer whose work is romantic, dark, dramatic, and whimsical. ', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('146', 'Artist Descending a Staircase', 'by Tom Stoppard, directed by John Hurley', 'Art, history, and a beautiful blind woman. When Donner is found dead at the bottom of the stairs, Martello and Beauchamp each think the other has killed him. In perspectives weaving through time, life and love, each investigates memory and motive while unraveling the relationship they all shared.  This is the first professional revival of the Stoppard work since its 1989 Broadway premiere. (performed in repertory with Giant-N-Variation and All for Love)', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('147', 'Two By Tenn', 'Tennessee Williams', 'a couple of one-act plays:
"Lord Byron''s Love Letter" and
"Talk to Me Like The Rain and Let Me Listen..."', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('148', 'The Bubble', 'by Frank J. Avella', 'THE BUBBLE is hilarious journey into the mind of a determined playwright as he attempts to write the perfect play, bringing to life a host of crazy characters who declare mutiny on him and force him to reevaluate his work. The focus then shifts toward the bizarre milieu of the rehearsal process where parallel characters are immersed in theatrical and carnal politics while the driven playwright plots to make certain his production is a success. The work finally 
culminates in the play itself, where our scribe is able to work out his personal demons and autobiography and memory run amok. ', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('149', 'Meaningful Sex', 'By and starring Seth Bisen-Hersh', 'Meaningful Sex - an act about the ins and outs of relationships: Composer of "Meaningless Sex" & "The Gayest Straight Man Alive"  Also starring Rori Nogee', 'Costume Design');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('150', 'Let''s Just Be Friends!', 'Directed by Anna Gorman & Peter Pinto', 'Let''s Just Be Friends!
The Lighter Side of Being Dumped

Put down the ice cream, turn off friends re-runs, burn that photo of
your ex and join us for a delightful night of Musical Theatre and Quirky
Pop songs aimed to cheer your love hungry soul.


Always, 
Seth 

', 'Set Design');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('151', '''Tis Pity She''s A Whore', 'by John Ford, directed by Alex Lippard', 'Set in Parma, Italy, ''TIS PITY SHE''S A WHORE tells the tale of an incestuous love between Giovanni and his sister Annabella that ends in spectacular violence. Written in 1630, this controversial story of lust, jealousy and betrayal is shockingly modern. Playwright John Ford wrestles with those enduring forces of evil which plague us today: driving teens to slaughter jeering classmates, prompting clergy to cover up scandals, and deluding politicians who justify hypocrisy as righteousness. 


', 'Solo Performance');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('152', 'Twelfth Night: Illyrium Delrium', 'by William Shakespeare', 'The Shakespeare Classic - performed free and out of doors
Part of the play Outside! Festival', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('153', 'The Wall of Water', 'An nutty farce by Sherry Kramer', 'Meet Meg''s new roommates.  There''s Denice, a self-proclaimed "party girl" with a scrapbook of conquests.  There''s Judy, a food-obsessed research allergist.  And then there''s Wendi: certifiably insane, and already the bane of Meg''s existence.  <p><p>On one fateful day, Meg can''t wash away her anger with a hot shower.  What follows is a hilarious mix of mistaken identity, miscommunication, and bizarre transformation: THE WALL OF WATER, by Sherry Kramer.<p><p>Starring Bryn Boice*, Lindsay A. Goranson, Jocelyn Greene, Melissa Klein, Doug Cote, Alex C. Ferrill, Abe Goldfarb and Jeremy Rishe.  <p><p>Set designed by Scott Aronow and Sunita Prasad, lights by Edward Hodge, sound by Matt O''Hare, props by Kathy Avril, and costumes coordinated by Robin Mates.  Sean Goldman produces.<p><p>*Member, Actors'' Equity Association – Equity Approved Showcase', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('154', 'An Ideal Husband', 'by Oscar Wilde', 'An Ideal Husband is a sharply intelligent comedic farce that explores the potential downfall of Sir Robert Chiltern, a respected and seemingly irreproachable politician who is in danger of being exposed by the mischievous Mrs. Cheveley, after having discovered his scandalous past.  Set in London in 1895, at the end of the Victorian era, the play is a biting social commentary on false morality, social hypocrisy and the corruption of greed with more than a few similarities to current events.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('156', 'The Merchant of Venice', 'by William Shakespeare', 'The Shakespeare classic', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('157', 'Tzvika the Soldier', 'A play by Avi levi', 'A play about one soldier, one character who is a Metaphor for many, about losing our country and culture. The play is a result of along process which grew inside me since I finished my army Service, a process of sobering up and maturing. Tzvika is an absurd soldier, who took part in all Israelis wars, Served in all the check points and is part of the Israeli occupation.
Tzvika is a human puzzle which I put together based on real stories. 

', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('158', 'Stumps', 'by Mark Medoff', 'Two handicapped Vietnam veterans, Stephen Ryder and Jerry Marcus, want to make a high-class movie with explicit sex, a step beyond Last Tango in Paris. They elicit the interest of the young explicit film star, Fawn Sierra, who arrives in the hills of Austin for a meeting with her "manager," Calvin Rhodes, a "gentleman" who may be a minister or may be evil incarnate. Calvin''s dark personality slowly emerges as he tries to wrest the project from the writers. Trying to keep the events in balance is Lin Ryder, Stephen''s Vietnamese wife. Ultimately, Cal destroys all semblance of balance and Lin is able to reestablish order only through catastrophic violence of her own.

**This will be a show where each of the actors is paired with an actor/interpreter signing for the deaf and co-performing – 10 artists playing 5 roles.   Special Note:  There are violent, sexual and very disturbing moments in this play – Nobody under 16 admitted without a parent or guardian. ', 'Artistic Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('159', 'Desert Sunrise', 'written and directed by Misa Shulman', '"Desert Sunrise" describes a natural, simple bonding by people who are supposed to be afraid of each other.  It is a drama the arises out of a chance encounter between an Israeli soldier and a Palestinian man of this region.  Taking refuge in a desert wadi, the two men are initially antagonistic, but each embodies an openness that exists within the majorities within both societies.  They seemingly overcome their root distrust for each other until they are joined by the Palestinian man''s beloved, who embodies an odd, impermeable shell of ideology and radical zeal that neither of the men can penetrate.  

As the three reach into their own pasts, they not only begin to find similarities, but also begin to understand the psychological and social fabric behind their political beliefs. Using humor, music, poetry and dance the play unfolds toward its sorrowful yet hopeful ending. Over the course of one memorable night the process of mutual understanding and forgiveness begins, halts, gets rejected, but is ultimately embraced by the pained characters. 

The play uses English, Hebrew and Arabic dialogue between the three characters and is interspersed with choral odes, performed by onstage musicians and adapted by Shulman from various translations of Aeschylus'' "Agamemnon."  It also employs Indonesian shadow techniques that are shared with Egyptian puppetry.

The choral odes are scored by Israeli musician Yoel Ben-Simhon (composer; appearing on tenor, oud, guitar and percussion).  He is an Israeli Jew of Moroccan descent.  Art direction and set design are by New York artist Celia Owens.  Lighting design is by Itai Erdal, who is from Israel but now based in Vancouver.
  ', 'Other');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('160', 'Medal Of Honor Rag', 'by Tom Cole', 'Based on a true story, MEDAL OF HONOR RAG details the relationship between a psychiatrist and one of his patients, a troubled Vietnam veteran. Dale "DJ" Jackson has been awarded the Congressional Medal of Honor for his bravery in Vietnam. Yet upon returning to the States, his life is soon forced into a downward spiral of depravity and depression. He eventually winds up at Valley Forge Hospital where he plows his way through several incompetent psychiatrists until finally meeting his match with a New York City-based doctor who, in one difficult session, forces him to face his demons. In the course of this first session, DJ''s story, both of Vietnam and his homecoming, unfolds, and the audience is allowed to witness the ramifications of a country that throws its young into a chaotic whirlpool and leaves them to fend for themselves upon returning home. ', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('161', 'Einstein Secret Letters (a love story)', 'by J.B. Edwards, directed by G. Beaudin', 'Based upon the recent discovery at the Princeton University Library of love letters written by Albert Einstein to his close friend Johanna Fantova, this play delves into the intense feelings they shared for one another. Einstein''s Secret Letters explores the great man''s dilemma of isolation and disappointment at the twilight of his life. The play also explores his humanitarian efforts and depicts his little known friendship with famed African American actor and social activist Paul Robeson. In this production, the startling portrayal of Einstein as a lover, pacifist, and critic of politics in Post War Israel and the United States are vividly brought to light.  
', 'Keyboard');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('162', 'Seekers', 'directed by Jadranka Andjelic', 'Performed by DAH Theatre Research Centre, Jadranka Andjelic Project

The 1990''s conflicts in the Republics that formerly made up Yugoslavia left the young artists of Serbia grappling with essential questions of war and peace that will permeate their work for many years to come.  One of the best examples of the Serbian movement of post-civil war performance is the women-led DAH Theatre Research Centre, whose motto is, "In the contemporary world, destruction and violence can only be opposed by the creation of sense."  "Seekers," a dance theater work by DAH Theatre Research Centre''s Jadranka Andjelic Project, is inspired by the poetry of Sufi master Hafiz and recalls a sister and brother, brought up in the Sufi tradition, who were heroes of World War II.  The piece is created by Jadranka Andjelic. 

The intricately choreographed piece is largely based on the poetry of Hafiz, a Sufi poet from XIV century Persia, who wrote, "Any thought that you are better or less/Than another man/Quickly/Breaks the wine glass."  Hafiz has influenced intellectuals and artists for centuries.  The bravery of this poet is his intentional breaking of clichés of mind and convention, rare even today.  Personal and direct, his poems remind us of our responsibility to create the world as we would like it to be. The performance uses translations of Hafiz'' poetry by Daniel Ladinsky from his book, "The Gift."', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('163', 'Out, Out Damned Clock: Faust meets Macbeth', 'By Nathaniel Green', 'Comedy-drama bringing together these two literary giants

', 'Festival');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('164', 'Woyzeck', 'Georg Buchner', 'Flying Pig Collective in collaboration with Boston Directors'' Lab presents an innovative and original site-specific production of Georg Buchner''s WOYZECK at Central Park''s Riftstone Arch (72nd Street and Central Park West). Bring your own seat and enjoy this haunting production. Bring your own seat!', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('165', 'The Caterers', 'by Jonathan Leaf, directed by Jose Zayas', 'In 1977, a group of Islamic radicals brought the Nation''s capitol to a two-day stand still, storming several buildings and holding 120 people hostage.  The act of terrorism was in response to Mohammed, Messenger of God, a film that the radical group, Hanafi, had deemed profanely offensive and sacrilegious. Twenty people were injured and a reporter was killed before hostage negotiators were finally able to end the siege.  Not a single member of Hanafi had ever viewed the film.
 
In THE CATERERS playwright Jonathan Leaf re-imagines these events in the present day, telling the story of two caterers who become trapped in a screening room the night of the film''s premiere.  Cornered by an Islamic radical, whose mission is to steal the blasphemous film, the couple, held hostage along with the film''s screenwriter, try to hold onto their lives and convince their captor that the film is not what it would seem. For a tense 80 minutes, the cat and mouse game ensues, as each of the four struggle to protect their art, their religion and their lives.
 ', 'Classical');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('166', 'The Secret Rapture', 'By David hare, Directed by Jesse Berger', 'Sometimes an act of kindness can be destructive. When their father dies two estranged sisters, one virtuous and one pragmatic, are forced to put his affairs in order. Among the problems they encounter is their alcoholic step-mother. Manipulation, chaos, and sacrifice are all part of this account that comes to a violent end.  
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('167', 'Platinum Travel Club', 'By Franca Miraglia', ' NPT is pleased to announce the U.S. premiere of Platinum Travel Club by Franca Miraglia, a product of our Women''s Work Residency Project.  The production opens Tuesday, October 4th and runs through Saturday, October 22, 2005.  Performances are Tuesday – Saturday at 8:00pm, with a special performance on Monday, October 17th at 7:00pm. 
	
Platinum Travel Club is an erotic-thriller that explores one woman''s road from childhood loss to adult obsession. The abduction of her beautiful teenage sister (Caroline) leaves Sandie to survive a shattered family shrouded in deceit and denial.  Despite this tragedy, she doesn''t let anything get in the way of building a successful career – neither a neglectful mother nor a dominating father. Switching between past and present, the story unfolds against a backdrop of Sandie''s involvement in a business travelers'' sex club as she confronts the ghosts from her damaged childhood.

Anne Beaumont directs the production, which features Christiane Amorosia, Andrew Platner, Joan Schumacher, Kevin G.Shinnick, Tony Neil, and Anne Winkles.

PERFORMANCE INFORMATION

WHERE:	New Perspectives Theatre Company
750 8th Avenue (46th/47th Streets), 6th Fl.

WHEN:		Tuesday, October 4, 2005 to Saturday, October 22, 2005
		Tuesday – Saturday at 8:00pm
		Special Performance: Monday, October 17, 2005, 7:00pm

		Reservations:  212-730-2030; info@newperspectivestheatre.org
	


', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('168', 'Moma''s Boyz', 'by Caindido Tirado', 'Moma''s Boyz is a magical tale of three young men from the projects, Shine, Thug and Mimic, who become entangled in the drug life. One bad decision leads to the death of one of the young men. While at his funeral, one of his friends wishes that he could turn back time to the days when a big deal meant they had to ask their mothers for money, and a magical force intervenes turning time back to when they made the fateful decision to sell drugs. The strength and heart of Momma''s Boyz lies in the belief that people have the power to change their own lives. 

The play is produced by the newly formed theatre company, Experimental Play Productions.', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('169', 'Saint Oedipus', 'written and directed by Piotr Tomaszuk', 'SAINT OEDIPUS -- which reflects on the myth of Oedipus and the nature of human sexuality -- is performed as a psychedelic game between two actors:  a man and a woman, a mother and a son.   Piotr Tomaszuk, who drew from the Oedipal myth, and  from Thomas Mann''s novels "Doctor Faustus" and "The Holy Sinner," the book of Psalms and the medieval tales "Gesta Romanorum" to create this original  work for the stage.
 
SAINT OEDIPUS is performed by Edyta Lukaszewicz-Lisowska and Rafal Gasowski. Scenic design is by Jan Zavarsky, costume design by Eva Farkasova, music by Piotr Nazaruk, with direction and lighting by Piotr Tomaszuk.
 
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('170', 'The American Dream and Other Fractured Fairy Tales', '10 Different Authors', 'What is "The American Dream?"  Is it real? Or is it just an ideal?  And how do you get it?  Does it inspire us?  Or enslave us?  "The American Dream and Other Fractured Fairy Tales," highlights a cross section of characters as they struggle to try and find some meaning in their lives, some common sense to hold on to and to attain their "American Dream" in the often harsh, confusing and sometimes, frightening landscape that is today''s America.  

Combining live music and stories by Jesse Cameron Alick, Erin Blackwell, Cusi Cram, Steven Dietz, Brian Dykstra, Rebecca Gilman, Kristina Halvorson, Allison Moore, Robin Rothstein & Sarah Schulman, their poignant, often hysterically funny and heartbreaking tales bring to life the daily battle against ignorance, greed and overwhelming apathy.

Cast: Stephen Byers*, Cherish Monique Duke, David A. Ellis*, Talene Kelly, Jerome McIntosh, Jessica Myhr, Jack Perry, Grace Savage & Liza St. John*.

Conceived & Directed by: Deborah Mathieu-Byers
Stage Manager: Jessica Pecharsky*
Musical Director: Stephen Byers
Lighting Design: Annmarie Duggan & Christopher Reising for AMD DESIGNS
Sound Engineer: Mike Gonzalez
Stage Design & Poster Art: Deborah Mathieu-Byers
Assistant Stage Manager: Jodi M. Witherell
Box Office & Concessions Manager: Jules Leo

* a member of Actors Equity Association/An Equity Approved Showcase
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('171', 'Jigsaw', 'written and directed by Jayson MacDonald', 'The discovery of an infant''s remains on a construction site begins an investigation that leads a priest and an archivist on a chase through time. Following the yellowed pages of a book called *Jigsaw*, which chronicles a similar investigation of forty years earlier, the protagonists begin to wonder if the mystery of the infant''s death is doomed to repeat itself time and again.

As they are drawn deeper into the mystery they become inextricably caught up in the events, and their only recourse is to solve the puzzle that begins and ends in a dark and ill-fated edifice, *The Rose Hotel *.

', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('172', 'Pack of Lies', 'by Hugh Whitemore', 'What would you do if the government asked your help in investigating your best friends?  That was the very real dilemma faced by the Jackson family when, in the late Autumn of 1960, an MI5 Agent requested the use of their home as a surveillance post for an ongoing inquiry.  

Based on the true story of one of the most famous espionage cases of the Cold War era, it''s a gripping study of an ordinary family thrust into extraordinary circumstances.  

', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('173', 'Broad, Bimbo, Brunette', 'Directed by David Cleveland', '...a peek inside an addled mind... Starring Cara Burdick
Featuring original music by Joel B. New
With special guest Maria Pendolino
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('174', 'Murdering Marlowe', 'By Charles Marowitz', 'The "green-eyed monster" of jealousy between playwrights William Shakespeare and Christopher Marlowe comes to life in "Murdering Marlowe," a brilliant new play by Charles Marowitz. Jason King Jones directs this apocryphal thriller in its east coast premiere, onstage at the Access Theater from Tuesday, October 11 through Sunday, October 23.<p><p>Up-and-coming writer Will Shakespeare is trying to make a name for himself in London''s theatre scene. Only 29 years old and stuck in a loveless marriage, Shakespeare''s home life fares little better than his writing career, as he toils under the shadow of literary giant, Christopher Marlowe. Will''s luck changes when the bawdy and brash Marlowe falls out of favor with the moralistic Crown government, and he suddenly finds himself poised to depose the "king" of the Elizabethan stage.<p><p>William Shakespeare is played by Cedric Hayman, whose Off-Broadway credits include "Richard III" with the Acting Company and "Unbound" with the Prospect Theatre Company. Christopher Marlowe is played by Glenn Peters, who comes to the show just from his performance in "The Shaggs: Philosophy of the World" with the 2005 New York Musical Theatre Festival. Off-Broadway credits include "The Turn of the Screw," "Murder by Poe," and "The Two Gentlemen of Verona."<p><p>Rounding out the cast of nine are Jeremy Beazlie as Ingram Frizer, Bryan Cogman as Henry Maunder, Nicholas Coleman as the Henchman, Patrick Hallahan as Robert Poley, Caralyn Kozlowski as Emilia, Tim McGeever as Philip Henslowe, and Mandy Olsen as Anne Hathaway.<p>The world of sixteenth-century London will be created by set designer Brian J. Ruggaber, costume designer Maggie Dick, lighting designer Aaron Spivey, and sound designer Zachary Quarles.<p><p>In Actu Theatre is an artists'' collective that utilizes the collaborative nature of theatre to rouse its members and the community into action by creating a forum for passionate discourse. The company celebrates the immediacy and transience of the theatrical experience by continually generating compelling, socially-relevant, and classically-inspired works. "Murdering Marlowe" is In Actu Theatre''s inaugural production.<p><p>Located in the heart of the downtown theater scene, on the fourth floor of 380 Broadway (two blocks south of Canal Street), The Access Theater is a 64-seat black box in a former textile warehouse in TriBeCa. The venue has recently played host to various Fringe Festival companies as well as the hit play, "Busted Jesus Comix."', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('175', 'That Way Madness Lies', 'A Montage of Macabre Tales', 'An ensemble of ten actors create a unique theatre event from the stories of Poe, Ogden, King, Shakespeare, Euripides, and the Theatre du Grand Guignol', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('176', 'POETICS: a ballet brut', 'conceived & directed by Pavol Liska', 'POETICS: a ballet brut, conceived and directed by PAVOL LISKA, is a non-verbal performance that strips theater down to its barest physical essentials and swarms the entire architecture of the Theatre of the Riverside Church. 2000 years after Aristotle''s original Poetics Liska asks – can we forge a new aesthetic?<p><p>PAVOL LISKA (director) was born and raised in Slovakia.  For the past 10 years he has directed his own as well as others'' plays at venues around the city, including Ontological-Hysteric Theater, Classic Stage Company, Theater for the New City, P.S.122, Chashama, and the Collective:Unconscious.  Poetics was originally presented as a work in progress for Prelude ''05, a festival of contemporary theatre, at CUNY Graduate Center.  This spring Pavol will be collaborating with Obie award-winning playwright Chuck Mee, Jr. on Fragment 147 at Classic Stage Company.', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('177', 'Estrella', 'by Kate Bell', 'A new play that deals with the haves and the have-nots, the disparity of middle-class America compared with refugees from Third World countries, in this case, El Salvador.   
 
In "Estrella," the story centers around two women: the characters of Lisa and Estrella.  The two women first meet in the early 1980s when Estrella, a refugee from the civil war in El Salvador, finds sanctuary in the child Lisa''s church/safe haven in Arizona.  Years  later, when Lisa is a young idealist fresh from law school, Estrella comes back into her life, appearing on Lisa''s doorstep and demanding that the young woman take her back to El Salvador to die.  As Lisa grapples with Estrella''s request, as well as the homeless woman''s failing health and psyche, she revisits memories of growing up in a "sanctuary church," and the struggles of politics and faith, love and war, that defined her young life.  In a larger sense, "Estrella" examines the meanings of sanctuary, hope, and freedom as it moves between these two periods in history and reveals how they affect the two women.
', 'Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('178', 'The Taming of the Shrew', 'by William Shakespeare', 'Come and enjoy a wild ride through Shakespeare''s rough and tumble world of courtship and marriage with The Queen''s Company''s unique production of Shakespeare''s The Taming of the Shrew, with an all-feamale cast

THE TAMING OF THE SHREW is Shakespeare''s classic comedy about love between a perfect pair of divas. Everybody loves Bianca (played by a blow-up doll) but no one can marry her until her feisty older sister, Kate, is married off. Enter Petruchio, a finger-lickin'' ladies man on the lookout for a wealthy wife. Let the fireworks begin! Happy ending guaranteed.
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('179', 'Butterflies Are Free', 'by Leonard Gershe', 'A funny, touching and thought-provoking play that takes the audience on an emotional ride while confronting fears of self confidence, personal responsibility and the risks that go along with loving someone.', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('180', 'The Cobra Lady Strikes', 'by Todd Michaels', '"The Cobra Lady Strikes" is a hysterical spoof of 1940s movie serials.  The diabolical Cobra Lady has secured the plans for a weapon of destructive power called The Dynamic Vibrator.  With the aid of a mad scientist, she hopes to build the device to fulfill her dream of world conquest.  Can a wisecracking girl newspaper reporter and a Broadway musical theatre leading man stop the Cobra Lady in time?  To be continued....

This play will be appearing in the 2005 Spotlight On Halloween Festival, presented by Spotlight On Productions and Frank Calo.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('181', 'Hell Cab', 'by Will Kern, directed by Akia', 'Hell Cab is a day in the life story of a cab driver in for the longest night of his life as he transports a bizarre and mysterious collection of customers through the gritty streets of Chicago.

Throughout his long shift the bizarre and eclectic collection of passengers who enter our Hero''s cab, a trio of drug-addicts, a rape victim, a fellow cab driver, a smug lawyer, a born-again couple on their way to church, a randy couple on their way to a motel, and others bring  about an emotional and existential transformation.
', 'Comedian');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('182', 'The Winter''s Tale', 'William Shakespeare''s The Winter''s Tale', 'Jealous rage. Senseless loss. Beautiful redemption. Funny noses.

Shakespeare''s Winter''s Tale is a tragic comedy of abandonment, madness, sheep-shearing, and bears, with a magical conclusion.  This production, directed by Julia Whitworth, is a wild ride featuring clowns, hippies, stuffy Boston bureaucrats, music and dancing.

The Magis Theatre Company has been training, teaching, and developing as an ensemble over the past two years.  The members of this actor-driven company have come together to create heightened text performances that draw on techniques from the ancient theatre and the timeless world of Clown.  
', 'Lighting');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('183', 'Hail Satan', 'Mac Rogers', 'Tom''s new job seems normal enough unti he discovers that all of his co-workers are worshippers of Satan. This strikes Tom as hilarious until one Sunday he attends one of their services and learns this is such a thing as a soul... and such a thing as damnation. HAIL SATAN is a horror play for the Halloween season as well as a study of religious fanaticism and the terrible scars one generation can leave on the next.', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('184', 'After The Fall', 'By Arthur Miller', '"After the Fall" presents the riveting struggle of a man attempting to make peace with history - his own and the world''s - in order to go forward with his life. Haunted by this relationship with a needy sex symbol, Quentin''s remarks to an unseen listener spark a relentless exploration of the past motives and compromises that still shape his present.', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('185', 'That Way Madness Lies', 'directed by Christa Savery', 'A Montage of Macabre Tales just in time for Halloween.  This show features an ensemble of ten actors, who have crafted a unique theatre event from the stories of Poe, King, Ogden, Shakespeare, Euripides, and the Theatre du Grand Guignol. The morbid tales presented are sometimes reminiscent of campfire stories, and the overall feeling of the show is an interesting halfway point between live storytelling and full-scale theatre.

The show runs at two locations: 
La  Nacional, $15
239 West 14th Street [between 7th and 8th Avenues]

October 23rd, 24, 25 & 26th at 8:00 PM at
Take 1,2,3 A,C or E train to 14th

and

The Creek Theatre  $10

10-93 Jackson Ave L.I.C NY 11101 [cross st 49th Ave]

October 27, 28, & 30th at 7:30 PM
also 29th [matinee at 2pm]

(Take the #7 train to Vernon-Jackson, just one stop
past Grand Central Station).
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('186', 'Deathwatch and The Maids', 'by Jean Genet', 'The all-male Egress Company presents two works by Jean Genet in rotating repertory.

The Maids follows  two sisters through their grotesque and ritualistic impersonations of their  employer and subsequent designs to destroy her.

Deathwatch explores the hierarchy of crime  underlying the twisted relationships between three prison convicts. In their  feverish competition to outdo one another, two inmates will stop at nothing,  even murder, to win the admiration of the highest-ranking criminal in the cell.
', 'Actress');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('187', 'Cowboy v. Samuari', 'by Michael Golamco', 'An adaptation of Edmond Rostand''s classic romantic comedy, CYRANO de BERGERAC, set in the wilds of Breakneck, Wyoming -- performed by an Asian-American cast,

When a mysterious and beautiful Asian-American woman moves to Breakneck, Wyoming, everyone falls in love with her, the samurai, the cowboy, and especially Travis (COWBOY V. SAMURAI''s Cyrano) - the Asian American teacher who doesn''t stand a chance. In this romantic comedy love letters are sealed and bound, horses set ablaze and the history of the railroads are deconstructed all the while the hand of the fair maiden is at stake.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('188', 'Saddam: The Musical', 'by Joe Beck, directed by Robert Kiernam', 'A madcap, screwball comedy about Saddam''s failed efforts to resuscitate his marriage
and emerge victorious from a raging mid-life crisis.

Saddam: The Musical tells the inside story of how Saddam Hussein was an eager to please henpecked husband and relates the tale of Saddam''s kidnapping of the world''s greatest lyricists and songwriters to be the ghostwriters of Saddam''s ultimate paean of love. As the walls of his palaces crumble about him, Saddam is obsessed with creating the one song that will both memorialize his musical genius and win back the heart of his first wife. ', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('189', 'The Revenger''s Tragedy', 'adapted and directed by Jesse Berger', 'The Revenger''s Tragedy, written just a few years after Hamlet, is a pot-boiling pastiche of the plays of Shakespeare and his contemporaries.  Set in a corrupt and mythical Venice, the protagonist Vindice (Matthew Rauch) vows revenge on the salacious Duke who murdered his fiancée.  This sets off a chain reaction of vengeance through which Vindice wreaks gleeful havoc on the city, exposing the court''s outrageous indulgences and government hypocrisy, ending in a coup de théâtre massacre of epic proportions.
 
The Revenger''s Tragedy is a searing examination of the precarious balance between the need for justice and the desire for vengeance.  This Jacobean masterpiece will be receiving its first major presentation in New York City in nearly 20 years.  Part black comedy, part social satire, the play is full of humorous macabre turns, and more plot-twists than a blender full of Shakespeare''s greatest hits.  It''s a roller-coaster ride through a Jacobean house of horrors as Shakespearean characters swirl around you and the play catapults you through a Venice you never dreamed existed.  Fellini, Coppola and Tarantino meet Shakespeare and the results are incendiary.
 
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('190', 'The Deluxe Illustrated Body', 'By Lil Malinich and Jasyon McDonald', 'The death of a family patriarch leaves a young woman to raise her teenage sister and exposes realities and secrets that lead to wrenching but necessary self-confrontation and change.  A marriage of thirty years is tested, a priest wrestles with a crisis of faith, a young man descends into alcoholism and a young woman confronts her inability to forgive, even in the face of death.', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('191', 'The Gayest Straight Man Alive', 'By and Starring Seth Bisen-Hersh', 'The Gayest Straight Man Alive is a humorous but poignant response to the fact that most people immediately (for some unknown reason) assume Bisen-Hersh is gay when they meet him, even though he is actually, surprisingly straight.  Topics include transvestite tendencies, masturbation, loneliness, internet dating, odd jobs and maintaining one''s sanity by  owning a cat & tivo.  There will also be a special guest appearance by a certain celebrity pig.
', 'Comedy');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('192', 'Full Moon Follies', 'Directed by Courtney Hebert', 'Full Moon Follies
A Haunting Night of Frightful Songs! Death by Show tunes! 

Featuring members & guests of the acclaimed ensemble of Rising Sun! 
Accompanied by Seth Bisen-Hersh
', 'Drama');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('193', 'The Barbie Project', 'directed by Michael Schiralli', 'The world premiere workshop exploring the many ways Barbie dolls find into our lives, as told via vaudeville-cabaret musical performances, monologues, dance and visual art

', 'Artistic Director');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('194', 'Cheeks', 'By Guillermo Gentile', 'CHEEKS is a story is about John, a disabled child who grows in a basement, isolated from the world and under the over protecting care of his Daddy who is everything to him. Due to his physical impediments, John can''t kiss or shake hands, so he expresses his feelings of love and affection by puffing his cheeks

Daddy provides and fulfills his son''s every need, but there is something he can''t provide - a friend.  The drama ignites when John''s desire to have a friend leads him to leave his basement world for the first time.  John meets Martin, a paranoid dreamer who has just escaped from an insane asylum, and brings him into his world.
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('195', 'William Shakespeare’s Haunted Pier', 'Created and directed by Mark Greenfield', 'An Interactive Halloween event featuring 20 performers leading audiences on a walking tour around Pier 25 and onto the docks of the historic Yankee Ferry.  As the audience travels through the "haunted pier," characters such as Macbeth and the Witches, Hamlet, Caliban and Romeo & Juliet will appear, each speaking words penned over 400 years ago.  Crowds will be lead through the Hall of Fairies from A Midsummer Night''s Dream, examine Julius Caesar''s wounds, dip toes into Ophelia''s Riverbed of Death (Hamlet),  journey through a Shakespearian Chamber of Darkness and dine at the table of Titus Andronicus.  

There will be a special section of the pier for youngsters – where the action isn''t quite so scary

', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('196', 'The Holy Terror', 'Adapted and directed by Kevin Connell,', 'An adaptation of Shakespeare''s Richard II
', 'Producer');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('197', 'Why We Have A Body', 'by Claire Chafee', 'WHY WE HAVE A BODY is a funny, lyrical play about two young women, Lili and her emotionally troubled sister, Mary, who ache for the return of their mother, Eleanor, who left home years ago to "get lost."  The play proceeds poetically through a collage of scenes in which the two sisters, their mother, and Lili''s new lover Renee, speak alternately to the audience and to each other, as they try to live with absence and great distance.  The women are taught few skills with which to navigate their lives, and in each case, the women''s chosen fields are a flight from traditional roles, propelled by a fear of getting stuck in a groove of routine.  The vast spaces that separate us from our past, from the ones we love, and from knowing ourselves constitute their landscape.  Through contrasts and contradictions, Chafee presents the struggle and search of these four women in a kaleidoscopic form, shifting space and time, as each character finds her own road signs to point the way.

Director:  Valerie Davenport
Stage Manager:  Meredith Kaufman
Assistant Stage Manager:  Jessica Franz
Lighting and Set Design:  Patrick Smith
Sound Design:  Beau Edmondson

Cast:  Laila Ayad* (Lili), Stefanie Black (Mary), Natasha Malinsky (Eleanor), Julie Lynn Stump (Renee)
* Appears Courtesy of Actor''s Equity Association

For more information please contact applegirlproductions@yahoo.com', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('198', 'Last Day', 'by jesse Schmitt', 'does love even exist?  what is our role in today''s over-populated society to pair off and mate?  Last Day is a funny, touching piece set to the familiar tune of wedding bells and one couples confused, earnest attempt to live up to their present while honoring their past.

Part of the Where Eagles Dare Fall Festival
', 'Actor');
INSERT INTO "theater"."plays" ("id", "act", "slug", "body", "genre") VALUES ('199', 'Suicide, the Musical', 'performced by Helen Stratford', '"Suicide, The Musical" is a punk rock opera recounting the story of a woman''s decisions to leave the comfort and security of a conventional but self-destructive relationship and her subsequent struggle to survive the challenges of a depraved and nocturnal New York City landscape, relying only on gifts of poetry and music and art. It is the story of the spiritual and artistic odyssey of a female Daedalus, a story of redemption found somewhere between the sacred and the profane, the creative and the degenerative.

Part of P.S. 122''s ongoing music-performance series "Schoolhouse Roxx"', 'Actor');
